/**
 * FreeWire Node Type Definitions
 * FreeLang Light 파이프라인과 1:1 대응하는 노드 타입 스펙
 */

const NODE_CATEGORIES = {
  UI:     'ui',
  STYLE:  'style',
  LOGIC:  'logic',
  EVENT:  'event',
  DATA:   'data',
  OUTPUT: 'output',
  AI:     'ai',
};

/**
 * 포트 타입 - 노드 간 연결 시 타입 호환성 검사용
 */
const PORT_TYPES = {
  COMPONENT: 'component',   // .free 컴포넌트 구조체
  STYLE:     'style',       // CSS 속성 객체
  EVENT:     'event',       // 이벤트 핸들러 함수
  LOGIC:     'logic',       // 조건/루프 표현식
  DATA:      'data',        // 상태/프롭스 값
  HTML:      'html',        // 최종 HTML 문자열
  CSS:       'css',         // 최종 CSS 문자열
  JS:        'js',          // 최종 JS 문자열
  ANY:       'any',         // 타입 무관 연결 허용
};

/**
 * 노드 타입 정의 맵
 * 각 타입은 { category, inputs, outputs, defaultProps, freelangBlock } 포함
 */
const NODE_TYPE_DEFS = {

  // ─── UI 노드 ────────────────────────────────────────────────
  'ui.component': {
    category: NODE_CATEGORIES.UI,
    label: '컴포넌트',
    description: '.free 컴포넌트 블록 생성',
    color: '#6366f1',
    inputs: [],
    outputs: [
      { id: 'out', label: '컴포넌트', type: PORT_TYPES.COMPONENT },
    ],
    defaultProps: {
      name: 'MyComponent',
      tag: 'div',
    },
    freelangBlock: 'component',
  },

  'ui.element': {
    category: NODE_CATEGORIES.UI,
    label: 'HTML 요소',
    description: '버튼, 입력창, 텍스트 등 기본 요소',
    color: '#6366f1',
    inputs: [
      { id: 'style', label: '스타일', type: PORT_TYPES.STYLE, required: false },
      { id: 'event', label: '이벤트', type: PORT_TYPES.EVENT, required: false },
    ],
    outputs: [
      { id: 'out', label: '요소', type: PORT_TYPES.COMPONENT },
    ],
    defaultProps: {
      tag: 'button',
      text: '클릭',
      className: '',
    },
    freelangBlock: 'markup',
  },

  'ui.text': {
    category: NODE_CATEGORIES.UI,
    label: '텍스트',
    description: '정적 또는 동적 텍스트 노드',
    color: '#6366f1',
    inputs: [
      { id: 'value', label: '내용', type: PORT_TYPES.DATA, required: false },
    ],
    outputs: [
      { id: 'out', label: '텍스트', type: PORT_TYPES.COMPONENT },
    ],
    defaultProps: {
      content: '안녕하세요',
      tag: 'p',
    },
    freelangBlock: 'markup',
  },

  // ─── 스타일 노드 ─────────────────────────────────────────────
  'style.css': {
    category: NODE_CATEGORIES.STYLE,
    label: 'CSS 스타일',
    description: '기본 CSS 속성 정의',
    color: '#10b981',
    inputs: [],
    outputs: [
      { id: 'out', label: '스타일', type: PORT_TYPES.STYLE },
    ],
    defaultProps: {
      color: '#000000',
      background: '#ffffff',
      padding: '8px',
      borderRadius: '4px',
      fontSize: '16px',
    },
    freelangBlock: 'style',
  },

  'style.animation': {
    category: NODE_CATEGORIES.STYLE,
    label: '애니메이션',
    description: '@animation 블록 - CSS 키프레임 자동 생성',
    color: '#10b981',
    inputs: [],
    outputs: [
      { id: 'out', label: '애니메이션', type: PORT_TYPES.STYLE },
    ],
    defaultProps: {
      name: 'fadeIn',
      duration: '0.3s',
      easing: 'ease-in-out',
      from: { opacity: 0 },
      to: { opacity: 1 },
    },
    freelangBlock: '@animation',
  },

  'style.glass': {
    category: NODE_CATEGORIES.STYLE,
    label: '글래스모피즘',
    description: '@glass 블록 - backdrop-filter 자동 생성',
    color: '#10b981',
    inputs: [],
    outputs: [
      { id: 'out', label: '글래스 스타일', type: PORT_TYPES.STYLE },
    ],
    defaultProps: {
      preset: 'card',
      blur: '10px',
      opacity: 0.2,
    },
    freelangBlock: '@glass',
  },

  'style.3d': {
    category: NODE_CATEGORIES.STYLE,
    label: '3D 변환',
    description: '@3d 블록 - perspective/rotate/translate',
    color: '#10b981',
    inputs: [],
    outputs: [
      { id: 'out', label: '3D 스타일', type: PORT_TYPES.STYLE },
    ],
    defaultProps: {
      perspective: '1000px',
      rotateY: '0deg',
      hoverRotateY: '15deg',
    },
    freelangBlock: '@3d',
  },

  // ─── 로직 노드 ───────────────────────────────────────────────
  'logic.if': {
    category: NODE_CATEGORIES.LOGIC,
    label: '조건 분기',
    description: 'if/else 조건 처리',
    color: '#f59e0b',
    inputs: [
      { id: 'condition', label: '조건', type: PORT_TYPES.DATA, required: true },
      { id: 'then',      label: 'true일 때', type: PORT_TYPES.ANY, required: true },
      { id: 'else',      label: 'false일 때', type: PORT_TYPES.ANY, required: false },
    ],
    outputs: [
      { id: 'out', label: '결과', type: PORT_TYPES.ANY },
    ],
    defaultProps: {
      condition: 'value > 0',
    },
    freelangBlock: 'if',
  },

  'logic.loop': {
    category: NODE_CATEGORIES.LOGIC,
    label: '반복',
    description: 'for 루프 - 리스트 렌더링',
    color: '#f59e0b',
    inputs: [
      { id: 'items',    label: '배열', type: PORT_TYPES.DATA,      required: true },
      { id: 'template', label: '템플릿', type: PORT_TYPES.COMPONENT, required: true },
    ],
    outputs: [
      { id: 'out', label: '목록', type: PORT_TYPES.COMPONENT },
    ],
    defaultProps: {
      itemName: 'item',
      indexName: 'i',
    },
    freelangBlock: 'for',
  },

  'logic.switch': {
    category: NODE_CATEGORIES.LOGIC,
    label: '스위치',
    description: '다중 조건 분기',
    color: '#f59e0b',
    inputs: [
      { id: 'value', label: '값', type: PORT_TYPES.DATA, required: true },
    ],
    outputs: [
      { id: 'default', label: '기본', type: PORT_TYPES.ANY },
    ],
    defaultProps: {
      cases: ['case1', 'case2'],
    },
    freelangBlock: 'switch',
  },

  // ─── 이벤트 노드 ─────────────────────────────────────────────
  'event.click': {
    category: NODE_CATEGORIES.EVENT,
    label: '클릭 이벤트',
    description: 'onClick 핸들러 생성',
    color: '#ef4444',
    inputs: [
      { id: 'action', label: '실행 동작', type: PORT_TYPES.LOGIC, required: true },
    ],
    outputs: [
      { id: 'out', label: '이벤트', type: PORT_TYPES.EVENT },
    ],
    defaultProps: {
      preventDefault: false,
      stopPropagation: false,
    },
    freelangBlock: 'script',
  },

  'event.hover': {
    category: NODE_CATEGORIES.EVENT,
    label: '호버 이벤트',
    description: 'onMouseEnter/Leave 핸들러',
    color: '#ef4444',
    inputs: [
      { id: 'enter', label: '진입', type: PORT_TYPES.LOGIC, required: false },
      { id: 'leave', label: '이탈', type: PORT_TYPES.LOGIC, required: false },
    ],
    outputs: [
      { id: 'out', label: '이벤트', type: PORT_TYPES.EVENT },
    ],
    defaultProps: {},
    freelangBlock: 'script',
  },

  'event.scroll': {
    category: NODE_CATEGORIES.EVENT,
    label: '스크롤 트리거',
    description: '@scroll 블록 - Intersection Observer',
    color: '#ef4444',
    inputs: [
      { id: 'action', label: '실행 동작', type: PORT_TYPES.LOGIC, required: true },
    ],
    outputs: [
      { id: 'out', label: '이벤트', type: PORT_TYPES.EVENT },
    ],
    defaultProps: {
      threshold: 0.1,
      once: true,
    },
    freelangBlock: '@scroll',
  },

  // ─── 데이터 노드 ─────────────────────────────────────────────
  'data.state': {
    category: NODE_CATEGORIES.DATA,
    label: '상태(State)',
    description: '반응형 상태 값 - GlobalStateManager 연동',
    color: '#8b5cf6',
    inputs: [
      { id: 'initial', label: '초기값', type: PORT_TYPES.DATA, required: false },
    ],
    outputs: [
      { id: 'value',  label: '값',      type: PORT_TYPES.DATA },
      { id: 'setter', label: '변경함수', type: PORT_TYPES.LOGIC },
    ],
    defaultProps: {
      name: 'count',
      initialValue: 0,
      type: 'number',
    },
    freelangBlock: 'script',
  },

  'data.props': {
    category: NODE_CATEGORIES.DATA,
    label: '프롭스(Props)',
    description: '컴포넌트 외부 입력 값',
    color: '#8b5cf6',
    inputs: [],
    outputs: [
      { id: 'out', label: '프롭스', type: PORT_TYPES.DATA },
    ],
    defaultProps: {
      name: 'value',
      type: 'string',
      defaultValue: '',
      required: false,
    },
    freelangBlock: 'props',
  },

  'data.constant': {
    category: NODE_CATEGORIES.DATA,
    label: '상수',
    description: '고정 값 노드',
    color: '#8b5cf6',
    inputs: [],
    outputs: [
      { id: 'out', label: '값', type: PORT_TYPES.DATA },
    ],
    defaultProps: {
      value: 'Hello',
      type: 'string',
    },
    freelangBlock: null,
  },

  // ─── 출력 노드 ───────────────────────────────────────────────
  'output.render': {
    category: NODE_CATEGORIES.OUTPUT,
    label: '렌더 출력',
    description: '최종 HTML/CSS/JS 생성 (FreeLang Light 번들러)',
    color: '#64748b',
    inputs: [
      { id: 'component', label: '컴포넌트', type: PORT_TYPES.COMPONENT, required: true },
      { id: 'style',     label: '스타일',   type: PORT_TYPES.STYLE,     required: false },
    ],
    outputs: [
      { id: 'html', label: 'HTML', type: PORT_TYPES.HTML },
      { id: 'css',  label: 'CSS',  type: PORT_TYPES.CSS },
      { id: 'js',   label: 'JS',   type: PORT_TYPES.JS },
    ],
    defaultProps: {
      filename: 'output',
      minify: false,
    },
    freelangBlock: null,
  },

  'output.preview': {
    category: NODE_CATEGORIES.OUTPUT,
    label: '미리보기',
    description: '브라우저 실시간 미리보기',
    color: '#64748b',
    inputs: [
      { id: 'html', label: 'HTML', type: PORT_TYPES.HTML, required: true },
      { id: 'css',  label: 'CSS',  type: PORT_TYPES.CSS,  required: false },
      { id: 'js',   label: 'JS',   type: PORT_TYPES.JS,   required: false },
    ],
    outputs: [],
    defaultProps: {
      width: 800,
      height: 600,
    },
    freelangBlock: null,
  },

  // ─── AI 노드 ─────────────────────────────────────────────────
  'ai.generate': {
    category: NODE_CATEGORIES.AI,
    label: 'AI 생성',
    description: '자연어 → 노드 그래프 자동 생성 (LLM)',
