    defaultProps: {
      prompt: '버튼을 클릭하면 카운트가 올라가는 컴포넌트',
      model: 'claude-haiku-4-5',
    },
    freelangBlock: null,
  },

  'ai.suggest': {
    category: NODE_CATEGORIES.AI,
    label: 'AI 제안',
    description: '현재 노드를 분석해 다음 노드 추천',
    color: '#ec4899',
    inputs: [
      { id: 'context', label: '현재 노드', type: PORT_TYPES.ANY, required: true },
    ],
    outputs: [
      { id: 'suggestions', label: '추천 목록', type: PORT_TYPES.ANY },
    ],
    defaultProps: {
      maxSuggestions: 3,
    },
    freelangBlock: null,
  },
};

module.exports = { NODE_CATEGORIES, PORT_TYPES, NODE_TYPE_DEFS };

/**
 * FreeWire - 공통 노드 스펙 (포트 타입, 검증 규칙)
 */

const PORT_TYPES = {
  COMPONENT: 'component',
  DATA:      'data',
  LOGIC:     'logic',
  EVENT:     'event',
  ANY:       'any',
};

const NODE_TYPES = {
  COMPONENT: 'component',
  DATA:      'data',
  LOGIC:     'logic',
  AI:        'ai',
};

/** 포트 타입 호환성 매트릭스 */
const PORT_COMPAT = {
  component: ['component', 'any'],
  data:      ['data', 'any'],
  logic:     ['logic', 'any'],
  event:     ['event', 'any'],
  any:       ['component', 'data', 'logic', 'event', 'any'],
};

/**
 * 두 포트가 연결 가능한지 검사
 * @param {string} outputType - 출력 포트 타입
 * @param {string} inputType  - 입력 포트 타입
 * @returns {boolean}
 */
function isCompatible(outputType, inputType) {
  const allowed = PORT_COMPAT[outputType] || [];
  return allowed.includes(inputType);
}

/**
 * 노드 JSON 기본 유효성 검사
 * @param {object} node
 * @returns {{ valid: boolean, errors: string[] }}
 */
function validateNode(node) {
  const errors = [];

  if (!node.id || typeof node.id !== 'string')
    errors.push('id: 문자열 필수');

  if (!node.type || !Object.values(NODE_TYPES).includes(node.type))
    errors.push(`type: ${Object.values(NODE_TYPES).join('|')} 중 하나여야 함`);

  if (!Array.isArray(node.inputs))
    errors.push('inputs: 배열 필수');

  if (!Array.isArray(node.outputs))
    errors.push('outputs: 배열 필수');

  if (typeof node.props !== 'object' || node.props === null)
    errors.push('props: 객체 필수');

  return { valid: errors.length === 0, errors };
}

/**
 * 엣지(연결선) 유효성 검사
 * @param {object} edge   { id, from: {nodeId, portId, portType}, to: {nodeId, portId, portType} }
 * @param {object[]} nodes - 전체 노드 목록
 * @returns {{ valid: boolean, errors: string[] }}
 */
function validateEdge(edge, nodes) {
  const errors = [];

  if (!edge.id) errors.push('edge.id 필수');
  if (!edge.from?.nodeId) errors.push('edge.from.nodeId 필수');
  if (!edge.to?.nodeId)   errors.push('edge.to.nodeId 필수');

  if (edge.from?.nodeId === edge.to?.nodeId)
    errors.push('자기 자신에게 연결 불가');

  if (edge.from?.portType && edge.to?.portType) {
    if (!isCompatible(edge.from.portType, edge.to.portType))
      errors.push(`포트 타입 불일치: ${edge.from.portType} → ${edge.to.portType}`);
  }

  const fromNode = nodes?.find(n => n.id === edge.from?.nodeId);
  const toNode   = nodes?.find(n => n.id === edge.to?.nodeId);
  if (!fromNode) errors.push(`출발 노드 없음: ${edge.from?.nodeId}`);
  if (!toNode)   errors.push(`도착 노드 없음: ${edge.to?.nodeId}`);

  return { valid: errors.length === 0, errors };
}

module.exports = { PORT_TYPES, NODE_TYPES, PORT_COMPAT, isCompatible, validateNode, validateEdge };

