/**
 * FreeWire - 노드 그래프 (노드 + 엣지 컨테이너)
 */

const { validateNode, validateEdge } = require('./node-spec');

class Graph {
  constructor(id = 'graph-001') {
    this.id    = id;
    this.nodes = [];   // { id, type, ... }
    this.edges = [];   // { id, from: {nodeId, portId, portType}, to: {nodeId, portId, portType} }
  }

  // ─── 노드 ─────────────────────────────────────────────────────
  addNode(node) {
    const { valid, errors } = validateNode(node);
    if (!valid) throw new Error(`노드 오류 [${node.id}]: ${errors.join(', ')}`);
    if (this.nodes.find(n => n.id === node.id))
      throw new Error(`중복 노드 id: ${node.id}`);
    this.nodes.push(node);
    return this;
  }

  removeNode(nodeId) {
    this.nodes  = this.nodes.filter(n => n.id !== nodeId);
    this.edges  = this.edges.filter(e => e.from.nodeId !== nodeId && e.to.nodeId !== nodeId);
    return this;
  }

  getNode(nodeId) {
    return this.nodes.find(n => n.id === nodeId) || null;
  }

  // ─── 엣지 ─────────────────────────────────────────────────────
  addEdge(edge) {
    const { valid, errors } = validateEdge(edge, this.nodes);
    if (!valid) throw new Error(`엣지 오류 [${edge.id}]: ${errors.join(', ')}`);
    if (this.edges.find(e => e.id === edge.id))
      throw new Error(`중복 엣지 id: ${edge.id}`);
    this.edges.push(edge);
    return this;
  }

  removeEdge(edgeId) {
    this.edges = this.edges.filter(e => e.id !== edgeId);
    return this;
  }

  /** 특정 노드의 입력 엣지 목록 */
  incomingEdges(nodeId) {
    return this.edges.filter(e => e.to.nodeId === nodeId);
  }

  /** 특정 노드의 출력 엣지 목록 */
  outgoingEdges(nodeId) {
    return this.edges.filter(e => e.from.nodeId === nodeId);
  }

  // ─── 위상 정렬 (실행 순서 결정) ──────────────────────────────
  topologicalSort() {
    const visited = new Set();
    const order   = [];

    const visit = (nodeId) => {
      if (visited.has(nodeId)) return;
      visited.add(nodeId);
      this.incomingEdges(nodeId).forEach(e => visit(e.from.nodeId));
      order.push(nodeId);
    };

    this.nodes.forEach(n => visit(n.id));
    return order.map(id => this.getNode(id));
  }

  // ─── 직렬화 / 역직렬화 ───────────────────────────────────────
  toJSON() {
    return { id: this.id, nodes: this.nodes, edges: this.edges };
  }

  static fromJSON(json) {
    const g = new Graph(json.id);
    (json.nodes || []).forEach(n => g.addNode(n));
    (json.edges || []).forEach(e => g.addEdge(e));
    return g;
  }

  // ─── 통계 ─────────────────────────────────────────────────────
  stats() {
    const typeCount = {};
    this.nodes.forEach(n => {
      typeCount[n.type] = (typeCount[n.type] || 0) + 1;
    });
    return {
      totalNodes: this.nodes.length,
      totalEdges: this.edges.length,
      byType: typeCount,
    };
  }
}

module.exports = { Graph };

