/**
 * FreeWire Phase 1 - 노드 스펙 테스트
 */

const { isCompatible, validateNode, validateEdge } = require('../core/node-spec');
const { createComponentNode, toFreelangMarkup }    = require('../core/nodes/component');
const { createDataNode, toFreelangCode: dataCode, inferType } = require('../core/nodes/data');
const { createLogicNode, toFreelangCode: logicCode }          = require('../core/nodes/logic');
const { Graph }                                               = require('../core/graph');

let pass = 0, fail = 0;

function test(name, fn) {
  try {
    fn();
    console.log(`  ✅ ${name}`);
    pass++;
  } catch (e) {
    console.log(`  ❌ ${name}: ${e.message}`);
    fail++;
  }
}

function assert(cond, msg) {
  if (!cond) throw new Error(msg || '실패');
}

// ─── node-spec ──────────────────────────────────────────────────
console.log('\n[1] node-spec: 포트 호환성');
test('data → data 호환',      () => assert(isCompatible('data', 'data')));
test('any → component 호환',  () => assert(isCompatible('any', 'component')));
test('component → data 불가', () => assert(!isCompatible('component', 'data')));
test('logic → event 불가',    () => assert(!isCompatible('logic', 'event')));

console.log('\n[2] node-spec: 노드 유효성 검사');
test('정상 노드 통과', () => {
  const { valid } = validateNode({
    id: 'n1', type: 'component',
    inputs: [], outputs: [], props: {},
  });
  assert(valid);
});
test('id 없으면 오류', () => {
  const { valid } = validateNode({ type: 'data', inputs: [], outputs: [], props: {} });
  assert(!valid);
});
test('잘못된 type 오류', () => {
  const { valid } = validateNode({ id: 'x', type: 'unknown', inputs: [], outputs: [], props: {} });
  assert(!valid);
});

// ─── component 노드 ─────────────────────────────────────────────
console.log('\n[3] component 노드');
test('button 노드 생성', () => {
  const n = createComponentNode('c1', 'button', { label: '저장' });
  assert(n.type === 'component');
  assert(n.componentType === 'button');
  assert(n.props.label === '저장');
});
test('card 노드 기본 props', () => {
  const n = createComponentNode('c2', 'card');
  assert(n.props.title === '카드 제목');
});
test('button → freelang markup', () => {
  const n = createComponentNode('c3', 'button', { label: '전송', variant: 'primary' });
  const code = toFreelangMarkup(n);
  assert(code.includes('<button'));
  assert(code.includes('전송'));
});
test('container → freelang markup', () => {
  const n = createComponentNode('c4', 'container');
  const code = toFreelangMarkup(n);
  assert(code.includes('flex'));
});

// ─── data 노드 ──────────────────────────────────────────────────
console.log('\n[4] data 노드');
test('number 상수 노드', () => {
  const n = createDataNode('d1', 'number', 42, { name: 'count' });
  assert(n.type === 'data');
  assert(n.props.value === 42);
  assert(n.props.name === 'count');
});
test('state 노드는 setter 포트 포함', () => {
  const n = createDataNode('d2', 'state', 0, { name: 'count' });
  assert(n.outputs.some(o => o.portId === 'setter'));
});
test('props 노드 freelangBlock = props', () => {
  const n = createDataNode('d3', 'props', '', { name: 'title' });
  assert(n.meta.freelangBlock === 'props');
});
test('number → freelang code', () => {
  const n = createDataNode('d4', 'number', 10, { name: 'x' });
  const code = dataCode(n);
  assert(code.includes('let x = 10'));
});
test('state → freelang code (setter 포함)', () => {
  const n = createDataNode('d5', 'state', 0, { name: 'count' });
  const code = dataCode(n);
  assert(code.includes('set_count'));
});
test('inferType 자동 추론', () => {
  assert(inferType(42)      === 'number');
  assert(inferType('hello') === 'string');
  assert(inferType([])      === 'array');
  assert(inferType({})      === 'object');
  assert(inferType(true)    === 'boolean');
});

// ─── logic 노드 ─────────────────────────────────────────────────
console.log('\n[5] logic 노드');
test('if 노드 생성', () => {
  const n = createLogicNode('l1', 'if', { condition: 'count > 0' });
  assert(n.logicType === 'if');
  assert(n.inputs.some(p => p.portId === 'condition'));
  assert(n.inputs.some(p => p.portId === 'then'));
  assert(n.inputs.some(p => p.portId === 'else'));
});
test('loop 노드 생성', () => {
  const n = createLogicNode('l2', 'loop');
  assert(n.inputs.some(p => p.portId === 'items'));
  assert(n.inputs.some(p => p.portId === 'template'));
});
test('map 노드 생성', () => {
  const n = createLogicNode('l3', 'map', { expression: 'item * 2' });
  assert(n.props.expression === 'item * 2');
});
test('if → freelang code', () => {
  const n = createLogicNode('l4', 'if', { condition: 'x > 10' });
  const code = logicCode(n);
  assert(code.includes('if (x > 10)'));
});
test('function → freelang code', () => {
  const n = createLogicNode('l5', 'function', { name: 'greet', params: ['name'], body: 'return "hi " + name;' });
  const code = logicCode(n);
  assert(code.includes('function greet'));
  assert(code.includes('name'));
});
test('알 수 없는 logicType 오류', () => {
  try { createLogicNode('l6', 'unknown'); assert(false); }
  catch (e) { assert(e.message.includes('알 수 없는')); }
});

// ─── Graph ──────────────────────────────────────────────────────
console.log('\n[6] Graph');

const btn   = createComponentNode('c10', 'button', { label: '클릭' });
const count = createDataNode('d10', 'state', 0, { name: 'count' });
const ifN   = createLogicNode('l10', 'if', { condition: 'count > 5' });

test('노드 추가', () => {
  const g = new Graph();
  g.addNode(btn).addNode(count).addNode(ifN);
  assert(g.nodes.length === 3);
});
test('중복 노드 id 거부', () => {
  const g = new Graph();
  g.addNode(btn);
  try { g.addNode({ ...btn }); assert(false); }
  catch (e) { assert(e.message.includes('중복')); }
});
test('엣지 연결 (data → component)', () => {
  const g = new Graph();
  g.addNode(btn).addNode(count);
  g.addEdge({
    id: 'e1',
    from: { nodeId: 'd10', portId: 'value',  portType: 'data' },
    to:   { nodeId: 'c10', portId: 'data',   portType: 'data' },
  });
  assert(g.edges.length === 1);
});
test('포트 타입 불일치 거부', () => {
  const g = new Graph();
  g.addNode(btn).addNode(count);
  try {
    g.addEdge({
      id: 'e2',
      from: { nodeId: 'c10', portId: 'out',   portType: 'component' },
      to:   { nodeId: 'd10', portId: 'value',  portType: 'data' },
    });
    assert(false);
  } catch (e) { assert(e.message.includes('포트 타입')); }
});
test('자기 자신 연결 거부', () => {
  const g = new Graph();
  g.addNode(btn);
  try {
    g.addEdge({ id: 'e3',
      from: { nodeId: 'c10', portId: 'out',  portType: 'component' },
      to:   { nodeId: 'c10', portId: 'data', portType: 'any' },
    });
    assert(false);
  } catch (e) { assert(e.message.includes('자기 자신')); }
});
test('노드 제거 시 연결 엣지도 삭제', () => {
  const g = new Graph();
  g.addNode(btn).addNode(count);
  g.addEdge({ id: 'e4',
    from: { nodeId: 'd10', portId: 'value', portType: 'data' },
    to:   { nodeId: 'c10', portId: 'data',  portType: 'data' },
  });
  g.removeNode('d10');
  assert(g.nodes.length === 1);
  assert(g.edges.length === 0);
});
test('위상 정렬', () => {
  const g = new Graph();
  g.addNode(btn).addNode(count).addNode(ifN);
  g.addEdge({ id: 'e5',
    from: { nodeId: 'd10', portId: 'value',     portType: 'data' },
    to:   { nodeId: 'l10', portId: 'condition', portType: 'data' },
  });
  const sorted = g.topologicalSort();
  const dIdx = sorted.findIndex(n => n.id === 'd10');
  const lIdx = sorted.findIndex(n => n.id === 'l10');
  assert(dIdx < lIdx, 'data 노드가 logic 노드보다 먼저');
});
test('toJSON / fromJSON 직렬화', () => {
  const g = new Graph('g1');
  g.addNode(btn).addNode(count);
  const json = g.toJSON();
  const g2   = Graph.fromJSON(json);
  assert(g2.nodes.length === 2);
  assert(g2.id === 'g1');
});
test('stats 통계', () => {
  const g = new Graph();
  g.addNode(btn).addNode(count).addNode(ifN);
  const s = g.stats();
  assert(s.totalNodes === 3);
  assert(s.byType.component === 1);
  assert(s.byType.data      === 1);
  assert(s.byType.logic     === 1);
});

// ─── 결과 ───────────────────────────────────────────────────────
console.log(`\n${'─'.repeat(40)}`);
console.log(`결과: ${pass + fail}개 중 ${pass}개 통과, ${fail}개 실패`);
if (fail === 0) console.log('🎉 Phase 1 모든 테스트 통과!');
process.exit(fail > 0 ? 1 : 0);

