/**
 * FreeWire Phase 2 - Graph → .free 컴파일러 테스트
 */

const { Graph }           = require('../core/graph');
const { createComponentNode } = require('../core/nodes/component');
const { createDataNode }      = require('../core/nodes/data');
const { createLogicNode }     = require('../core/nodes/logic');
const { GraphCompiler }       = require('../compiler/graph-compiler');

let pass = 0, fail = 0;
const compiler = new GraphCompiler();

function test(name, fn) {
  try { fn(); console.log(`  ✅ ${name}`); pass++; }
  catch (e) { console.log(`  ❌ ${name}: ${e.message}`); fail++; }
}
function assert(cond, msg) { if (!cond) throw new Error(msg || '실패'); }
function assertIncludes(str, sub) {
  if (!str.includes(sub)) throw new Error(`"${sub}" 없음\n---\n${str}\n---`);
}

// ─── 1. 빈 그래프 ───────────────────────────────────────────────
console.log('\n[1] 빈 그래프');
test('경고 포함, 코드는 생성됨', () => {
  const g = new Graph('empty');
  const { code, warnings } = compiler.compile(g);
  assert(code.includes('component'), '컴포넌트 헤더 없음');
  assert(warnings.length > 0, '경고 없음');
});

// ─── 2. 버튼 하나 ───────────────────────────────────────────────
console.log('\n[2] 버튼 단독 컴포넌트');
test('button markup 생성', () => {
  const g = new Graph('btn-test');
  g.addNode(createComponentNode('c1', 'button', { label: '저장' }));
  const { code, errors } = compiler.compile(g);
  assert(errors.length === 0, errors.join(', '));
  assertIncludes(code, '<button');
  assertIncludes(code, '저장');
  assertIncludes(code, 'markup {');
});
test('component 헤더 포함', () => {
  const g = new Graph('my-graph');
  g.addNode(createComponentNode('c1', 'button'));
  const { code } = compiler.compile(g);
  assertIncludes(code, 'component ');
});

// ─── 3. 상태 + 버튼 ─────────────────────────────────────────────
console.log('\n[3] 상태(State) + 버튼');
test('state → script 블록 생성', () => {
  const g = new Graph('counter');
  g.addNode(createDataNode('d1', 'state', 0, { name: 'count' }));
  g.addNode(createComponentNode('c1', 'button', { label: '+1' }));
  const { code } = compiler.compile(g);
  assertIncludes(code, 'script {');
  assertIncludes(code, 'let count = 0');
  assertIncludes(code, 'set_count');
});
test('props 블록 생성', () => {
  const g = new Graph('with-props');
  g.addNode(createDataNode('d1', 'props', 'Hello', { name: 'title' }));
  g.addNode(createComponentNode('c1', 'text', { content: '제목', tag: 'h1' }));
  const { code } = compiler.compile(g);
  assertIncludes(code, 'props {');
  assertIncludes(code, 'title');
});

// ─── 4. 상수 데이터 ──────────────────────────────────────────────
console.log('\n[4] 상수 + 텍스트');
test('number 상수 → script', () => {
  const g = new Graph('const-test');
  g.addNode(createDataNode('d1', 'number', 42, { name: 'maxCount' }));
  g.addNode(createComponentNode('c1', 'text', { content: '값' }));
  const { code } = compiler.compile(g);
  assertIncludes(code, 'let maxCount = 42');
});
test('string 상수 → script', () => {
  const g = new Graph('str-test');
  g.addNode(createDataNode('d1', 'string', 'FreeLang', { name: 'brand' }));
  g.addNode(createComponentNode('c1', 'text'));
  const { code } = compiler.compile(g);
  assertIncludes(code, 'let brand = "FreeLang"');
});

// ─── 5. 로직 노드 ────────────────────────────────────────────────
console.log('\n[5] 로직 노드');
test('if 노드 → script if문 생성', () => {
  const g = new Graph('if-test');
  g.addNode(createDataNode('d1', 'state', 0, { name: 'count' }));
  g.addNode(createLogicNode('l1', 'if', { condition: 'count > 5' }));
  g.addNode(createComponentNode('c1', 'button'));
  const { code } = compiler.compile(g);
  assertIncludes(code, 'if (count > 5)');
});
test('function 노드 → 함수 선언 생성', () => {
  const g = new Graph('fn-test');
  g.addNode(createLogicNode('l1', 'function', {
    name: 'handleClick', params: ['e'], body: 'alert("클릭!");',
  }));
  g.addNode(createComponentNode('c1', 'button'));
  const { code } = compiler.compile(g);
  assertIncludes(code, 'function handleClick');
  assertIncludes(code, 'alert("클릭!")');
});
test('map 노드 → map 표현식 생성', () => {
  const g = new Graph('map-test');
  g.addNode(createDataNode('d1', 'array', [1,2,3], { name: 'nums' }));
  g.addNode(createLogicNode('l1', 'map', { itemName: 'x', expression: 'x * 2' }));
  g.addNode(createComponentNode('c1', 'list'));
  const { code } = compiler.compile(g);
  assertIncludes(code, '.map(function(x)');
  assertIncludes(code, 'x * 2');
});
test('filter 노드 → filter 표현식 생성', () => {
  const g = new Graph('filter-test');
  g.addNode(createDataNode('d1', 'array', [], { name: 'items' }));
  g.addNode(createLogicNode('l1', 'filter', { itemName: 'item', condition: 'item > 0' }));
  g.addNode(createComponentNode('c1', 'list'));
  const { code } = compiler.compile(g);
  assertIncludes(code, '.filter(function(item)');
  assertIncludes(code, 'item > 0');
});

// ─── 6. 스타일 블록 ──────────────────────────────────────────────
console.log('\n[6] 스타일 블록');
test('container → style 블록 생성', () => {
  const g = new Graph('style-test');
  g.addNode(createComponentNode('c1', 'container', {
    direction: 'row', gap: '16px', padding: '24px',
  }));
  const { code } = compiler.compile(g);
  assertIncludes(code, 'style {');
  assertIncludes(code, 'display: flex');
  assertIncludes(code, 'flex-direction: row');
});
test('text 색상 → style 블록', () => {
  const g = new Graph('color-test');
  g.addNode(createComponentNode('c1', 'text', { color: '#ff0000', tag: 'h1', content: '제목' }));
  const { code } = compiler.compile(g);
  assertIncludes(code, 'style {');
  assertIncludes(code, 'color: #ff0000');
});

// ─── 7. 엣지 연결 반영 ───────────────────────────────────────────
console.log('\n[7] 엣지 연결 반영');
test('data → logic 연결 시 script에 반영', () => {
  const g = new Graph('edge-test');
  const state  = createDataNode('d1', 'state', 0, { name: 'score' });
  const ifNode = createLogicNode('l1', 'if', { condition: 'score > 10' });
  const btn    = createComponentNode('c1', 'button');
  g.addNode(state).addNode(ifNode).addNode(btn);
  g.addEdge({ id: 'e1',
    from: { nodeId: 'd1', portId: 'value',     portType: 'data' },
    to:   { nodeId: 'l1', portId: 'condition', portType: 'data' },
  });
  const { code } = compiler.compile(g);
  assertIncludes(code, 'if (score > 10)');
});

// ─── 8. JSON 입력 지원 ───────────────────────────────────────────
console.log('\n[8] JSON 직렬화 → 컴파일');
test('Graph.toJSON() 결과를 그대로 컴파일', () => {
  const g = new Graph('json-test');
  g.addNode(createDataNode('d1', 'state', 0, { name: 'cnt' }));
  g.addNode(createComponentNode('c1', 'button', { label: '클릭' }));
  const json = g.toJSON();
  const { code, errors } = compiler.compile(json);
  assert(errors.length === 0, errors.join(', '));
  assertIncludes(code, 'let cnt = 0');
  assertIncludes(code, '<button');
});

// ─── 9. 전체 통합 예제 ───────────────────────────────────────────
console.log('\n[9] 전체 통합 - 카운터 앱');
test('카운터 앱 전체 .free 생성', () => {
  const g = new Graph('counter-app');

  const count   = createDataNode('d1', 'state',    0,       { name: 'count' });
  const maxVal  = createDataNode('d2', 'number',   10,      { name: 'max' });
  const handler = createLogicNode('l1', 'function', {
    name: 'increment', params: [], body: 'set_count(count + 1);',
  });
  const checkMax = createLogicNode('l2', 'if', { condition: 'count >= max' });
  const btn    = createComponentNode('c1', 'button',    { label: '증가' });
  const display = createComponentNode('c2', 'text',     { content: '{{count}}', tag: 'p' });
  const wrap   = createComponentNode('c3', 'container', { direction: 'column', gap: '8px' });

  g.addNode(count).addNode(maxVal).addNode(handler)
   .addNode(checkMax).addNode(btn).addNode(display).addNode(wrap);

  const { code, errors, warnings } = compiler.compile(g);

  assert(errors.length === 0, errors.join(', '));
  assertIncludes(code, 'component ');
  assertIncludes(code, 'script {');
  assertIncludes(code, 'let count = 0');
  assertIncludes(code, 'let max = 10');
  assertIncludes(code, 'function increment');
  assertIncludes(code, 'if (count >= max)');
  assertIncludes(code, 'markup {');
  assertIncludes(code, '<button');

  // 생성된 코드 출력
  console.log('\n  📄 생성된 .free 파일:');
  code.split('\n').forEach(l => console.log('  ' + l));
});

// ─── 결과 ───────────────────────────────────────────────────────
console.log(`\n${'─'.repeat(40)}`);
console.log(`결과: ${pass + fail}개 중 ${pass}개 통과, ${fail}개 실패`);
if (fail === 0) console.log('🎉 Phase 2 모든 테스트 통과!');
process.exit(fail > 0 ? 1 : 0);

