/**
 * FreeWire - .free 코드 → HTML/CSS/JS 실행기
 * FreeLang Light 컴파일러 로직을 내장하여 의존성 없이 동작
 */

class FreeExecutor {
  /**
   * @param {string} freeCode  - GraphCompiler가 생성한 .free 문자열
   * @param {object} graphJson - 원본 그래프 JSON (메타 정보 참조용)
   * @returns {{ html: string, css: string, js: string, stats: object }}
   */
  execute(freeCode, graphJson = {}) {
    const sections = this._parseSections(freeCode);

    const css  = this._compileStyle(sections.style);
    const js   = this._compileScript(sections.script);
    const html = this._compileMarkup(sections.markup);

    return {
      html,
      css,
      js,
      stats: {
        htmlBytes: html.length,
        cssBytes:  css.length,
        jsBytes:   js.length,
        sections:  Object.keys(sections).filter(k => sections[k]),
      },
    };
  }

  // ─── 파서: .free 섹션 분리 ──────────────────────────────────

  _parseSections(code) {
    const sections = { props: '', style: '', script: '', markup: '' };
    const pattern  = /\b(props|style|script|markup)\s*\{/g;
    let match;
    const positions = [];

    while ((match = pattern.exec(code)) !== null) {
      positions.push({ type: match[1], start: match.index + match[0].length });
    }

    positions.forEach((pos, i) => {
      const end   = i + 1 < positions.length
        ? this._findBlockEnd(code, pos.start - 1)
        : this._findBlockEnd(code, pos.start - 1);
      const inner = code.slice(pos.start, end).trim();
      sections[pos.type] += '\n' + inner;
    });

    return sections;
  }

  _findBlockEnd(code, openBrace) {
    // openBrace 위치에서 '{' 찾기
    let idx = openBrace;
    while (idx < code.length && code[idx] !== '{') idx++;
    let depth = 1;
    idx++;
    while (idx < code.length && depth > 0) {
      if (code[idx] === '{') depth++;
      else if (code[idx] === '}') depth--;
      idx++;
    }
    return idx - 1;
  }

  // ─── CSS 컴파일 ─────────────────────────────────────────────

  _compileStyle(styleBlock) {
    if (!styleBlock.trim()) return '';

    // camelCase → kebab-case
    return styleBlock
      .replace(/([a-z])([A-Z])/g, '$1-$2')
      .toLowerCase()
      .replace(/\s*\n\s*/g, '\n')
      .trim();
  }

  // ─── JS 컴파일 ──────────────────────────────────────────────

  _compileScript(scriptBlock) {
    if (!scriptBlock.trim()) return '';

    const lines = scriptBlock.split('\n').map(l => l.trim()).filter(Boolean);
    const output = [];

    output.push('(function() {');
    output.push('  "use strict";');

    lines.forEach(line => {
      // 주석 라인은 그대로
      if (line.startsWith('//')) {
        output.push('  ' + line);
        return;
      }
      // 변수 선언
      if (line.startsWith('let ') || line.startsWith('const ')) {
        output.push('  ' + line);
        return;
      }
      // 함수 선언
      if (line.startsWith('function ')) {
        output.push('  ' + line);
        return;
      }
      // if/else
      if (line.startsWith('if ') || line.startsWith('if(') ||
          line.startsWith('} else') || line === '}' || line === '{') {
        output.push('  ' + line);
        return;
      }
      // 기타 (map/filter/reduce 결과 등)
      output.push('  ' + line);
    });

    // DOM 준비 후 state 바인딩
    output.push('  // DOM 이벤트 바인딩');
    output.push('  document.addEventListener("DOMContentLoaded", function() {');
    output.push('    var btns = document.querySelectorAll("button");');
    output.push('    btns.forEach(function(btn) {');
    output.push('      btn.addEventListener("click", function() {');
    output.push('        if (typeof handleClick === "function") handleClick(this);');
    output.push('        if (typeof increment  === "function") increment();');
    output.push('        _updateDOM();');
    output.push('      });');
    output.push('    });');
    output.push('    _updateDOM();');
    output.push('  });');
    output.push('  function _updateDOM() {');
    output.push('    var displays = document.querySelectorAll("[data-bind]");');
    output.push('    displays.forEach(function(el) {');
    output.push('      var key = el.getAttribute("data-bind");');
    output.push('      try { el.textContent = eval(key); } catch(e) {}');
    output.push('    });');
    output.push('  }');
    output.push('})();');

    return output.join('\n');
  }

  // ─── HTML 컴파일 ────────────────────────────────────────────

  _compileMarkup(markupBlock) {
    if (!markupBlock.trim()) return '';

    let html = markupBlock
      // 중첩 markup { } 제거
      .replace(/markup\s*\{/g, '')
      .replace(/^\s*\}\s*$/gm, '')
      // {{변수}} → <span data-bind="변수">변수</span>
      .replace(/\{\{(\w+)\}\}/g, '<span data-bind="$1">$1</span>')
      // 빈 줄 정리
      .replace(/\n{3,}/g, '\n\n')
      .trim();

    return html;
  }
}

module.exports = { FreeExecutor };

