/**
 * FreeWire Phase 3 - API 서버 테스트 (서버 없이 직접 핸들러 테스트)
 */

const { GraphCompiler }       = require('../compiler/graph-compiler');
const { FreeExecutor }        = require('../api/free-executor');
const { Graph }               = require('../core/graph');
const { createComponentNode } = require('../core/nodes/component');
const { createDataNode }      = require('../core/nodes/data');
const { createLogicNode }     = require('../core/nodes/logic');

let pass = 0, fail = 0;
const compiler = new GraphCompiler();
const executor  = new FreeExecutor();

function test(name, fn) {
  try { fn(); console.log(`  ✅ ${name}`); pass++; }
  catch (e) { console.log(`  ❌ ${name}: ${e.message}`); fail++; }
}
function assert(cond, msg)         { if (!cond) throw new Error(msg || '실패'); }
function assertIncludes(str, sub)  {
  if (!str.includes(sub)) throw new Error(`"${sub}" 없음\n--- 실제 ---\n${str.slice(0,300)}`);
}
function assertNotIncludes(str, sub) {
  if (str.includes(sub)) throw new Error(`"${sub}" 있으면 안 됨`);
}

// 테스트용 그래프 빌더
function makeGraph(nodes = [], edges = []) {
  const g = new Graph('test-' + Date.now());
  nodes.forEach(n => g.addNode(n));
  edges.forEach(e => g.addEdge(e));
  return g;
}

// ─── 1. FreeExecutor: _parseSections ────────────────────────────
console.log('\n[1] FreeExecutor - 섹션 파싱');

test('style 섹션 추출', () => {
  const code = `component A {\n  style {\n    .btn { color: red; }\n  }\n  markup {\n    <div></div>\n  }\n}`;
  const sections = executor._parseSections(code);
  assertIncludes(sections.style, '.btn');
});
test('script 섹션 추출', () => {
  const code = `component A {\n  script {\n    let x = 1;\n  }\n  markup { <div/> }\n}`;
  const sections = executor._parseSections(code);
  assertIncludes(sections.script, 'let x = 1');
});
test('markup 섹션 추출', () => {
  const code = `component A {\n  markup {\n    <button>클릭</button>\n  }\n}`;
  const sections = executor._parseSections(code);
  assertIncludes(sections.markup, '<button>');
});
test('복수 섹션 동시 추출', () => {
  const code = `component A {\n  style { .a { color: blue; } }\n  script { let n = 0; }\n  markup { <p>hi</p> }\n}`;
  const s = executor._parseSections(code);
  assert(s.style.includes('.a'), 'style');
  assert(s.script.includes('let n'), 'script');
  assert(s.markup.includes('<p>'), 'markup');
});

// ─── 2. FreeExecutor: CSS 컴파일 ────────────────────────────────
console.log('\n[2] FreeExecutor - CSS 컴파일');

test('camelCase → kebab-case 변환', () => {
  const css = executor._compileStyle('  fontSize: 16px;\n  backgroundColor: #fff;');
  assertIncludes(css, 'font-size');
  assertIncludes(css, 'background-color');
});
test('빈 style → 빈 문자열', () => {
  assert(executor._compileStyle('') === '');
  assert(executor._compileStyle('   ') === '');
});
test('셀렉터 유지', () => {
  const css = executor._compileStyle('.container { display: flex; }');
  assertIncludes(css, '.container');
  assertIncludes(css, 'display');
});

// ─── 3. FreeExecutor: JS 컴파일 ─────────────────────────────────
console.log('\n[3] FreeExecutor - JS 컴파일');

test('IIFE 래퍼 생성', () => {
  const js = executor._compileScript('let x = 1;');
  assertIncludes(js, '(function()');
  assertIncludes(js, 'let x = 1');
  assertIncludes(js, '})()');
});
test('함수 선언 유지', () => {
  const js = executor._compileScript('function hello() { return 1; }');
  assertIncludes(js, 'function hello');
});
test('DOMContentLoaded 바인딩 포함', () => {
  const js = executor._compileScript('let count = 0;');
  assertIncludes(js, 'DOMContentLoaded');
  assertIncludes(js, '_updateDOM');
});
test('빈 script → 빈 문자열', () => {
  assert(executor._compileScript('') === '');
});

// ─── 4. FreeExecutor: HTML 컴파일 ───────────────────────────────
console.log('\n[4] FreeExecutor - HTML 컴파일');

test('markup 블록 제거, 태그 유지', () => {
  const html = executor._compileMarkup('  markup {\n    <button>클릭</button>\n  }');
  assertIncludes(html, '<button>클릭</button>');
  assertNotIncludes(html, 'markup {');
});
test('{{변수}} → data-bind span 변환', () => {
  const html = executor._compileMarkup('<p>{{count}}</p>');
  assertIncludes(html, 'data-bind="count"');
  assertIncludes(html, '<span');
});
test('빈 markup → 빈 문자열', () => {
  assert(executor._compileMarkup('') === '');
});

// ─── 5. execute() 통합 ──────────────────────────────────────────
console.log('\n[5] execute() 통합');

test('버튼 컴포넌트 execute', () => {
  const g = makeGraph([createComponentNode('c1', 'button', { label: '확인' })]);
  const { code } = compiler.compile(g);
  const out = executor.execute(code, g.toJSON());
  assert(typeof out.html === 'string', 'html 없음');
  assert(typeof out.css  === 'string', 'css 없음');
  assert(typeof out.js   === 'string', 'js 없음');
  assert(out.stats.htmlBytes > 0, 'htmlBytes 0');
});
test('state + button → js에 set_ 함수 포함', () => {
  const g = makeGraph([
    createDataNode('d1', 'state', 0, { name: 'count' }),
    createComponentNode('c1', 'button', { label: '+' }),
  ]);
  const { code } = compiler.compile(g);
  const out = executor.execute(code, g.toJSON());
  assertIncludes(out.js, 'set_count');
});
test('{{변수}} → HTML data-bind 속성', () => {
  const g = makeGraph([
    createDataNode('d1', 'state', 0, { name: 'score' }),
    createComponentNode('c1', 'text', { content: '{{score}}', tag: 'p' }),
  ]);
  const { code } = compiler.compile(g);
  const out = executor.execute(code, g.toJSON());
  assertIncludes(out.html, 'data-bind="score"');
});
test('stats 통계 포함', () => {
  const g = makeGraph([createComponentNode('c1', 'card', { title: '테스트' })]);
  const { code } = compiler.compile(g);
  const out = executor.execute(code, g.toJSON());
  assert(Array.isArray(out.stats.sections), 'sections 배열');
  assert(out.stats.sections.includes('markup'), 'markup 섹션');
});

// ─── 6. 전체 파이프라인 (Graph → compile → execute) ─────────────
console.log('\n[6] 전체 파이프라인');

test('카운터 앱 HTML/CSS/JS 생성', () => {
  const g = new Graph('counter');
  g.addNode(createDataNode('d1', 'state', 0, { name: 'count' }));
  g.addNode(createLogicNode('l1', 'function', {
    name: 'increment', params: [], body: 'set_count(count + 1);',
  }));
  g.addNode(createComponentNode('c1', 'button', { label: '증가' }));
  g.addNode(createComponentNode('c2', 'text',   { content: '{{count}}', tag: 'p', color: '#333' }));

  const { code, errors } = compiler.compile(g);
  assert(errors.length === 0, errors.join(', '));

  const out = executor.execute(code, g.toJSON());
  assertIncludes(out.html, '<button');
  assertIncludes(out.html, 'data-bind="count"');
  assertIncludes(out.js,   'function increment');
  assertIncludes(out.js,   'set_count');
  assertIncludes(out.css,  'color');
  assert(out.stats.sections.includes('script'), 'script 섹션');
  assert(out.stats.sections.includes('markup'), 'markup 섹션');
  assert(out.stats.sections.includes('style'),  'style 섹션');

  console.log(`\n  📊 카운터 앱 출력:`);
  console.log(`     HTML: ${out.stats.htmlBytes}B | CSS: ${out.stats.cssBytes}B | JS: ${out.stats.jsBytes}B`);
});

test('card + glass 스타일 컴포넌트', () => {
  const g = new Graph('card-demo');
  g.addNode(createComponentNode('c1', 'card', {
    title: 'FreeWire', content: '노드 기반 시각 언어',
    background: 'rgba(255,255,255,0.2)', borderRadius: '16px', padding: '24px',
  }));
  const { code } = compiler.compile(g);
  const out = executor.execute(code, g.toJSON());
  assertIncludes(out.html, 'FreeWire');
  assertIncludes(out.css,  'border-radius');
});

test('로직(if) + 버튼 파이프라인', () => {
  const g = new Graph('logic-test');
  g.addNode(createDataNode('d1', 'state', 0, { name: 'val' }));
  g.addNode(createLogicNode('l1', 'if', { condition: 'val > 10' }));
  g.addNode(createComponentNode('c1', 'button', { label: '체크' }));
  const { code } = compiler.compile(g);
  const out = executor.execute(code, g.toJSON());
  assertIncludes(out.js, 'if (val > 10)');
});

// ─── 7. HTTP 요청 시뮬레이션 ────────────────────────────────────
console.log('\n[7] HTTP 핸들러 시뮬레이션');

test('/api/compile 시뮬레이션 - 정상', () => {
  const graph = new Graph('sim').addNode(createComponentNode('c1', 'button')).toJSON();
  const result = compiler.compile(graph);
  assert(result.code.includes('component'), '컴포넌트 없음');
  assert(Array.isArray(result.errors), 'errors 배열');
  assert(Array.isArray(result.warnings), 'warnings 배열');
});

test('/api/execute 시뮬레이션 - 정상', () => {
  const g = new Graph('sim2');
  g.addNode(createDataNode('d1', 'state', 0, { name: 'n' }));
  g.addNode(createComponentNode('c1', 'button', { label: '클릭' }));
  const graph = g.toJSON();
  const { code, errors } = compiler.compile(graph);
  assert(errors.length === 0, errors.join(', '));
  const out = executor.execute(code, graph);
  assert(out.html, 'html 없음');
});

test('/api/compile 오류 케이스 - 빈 graph', () => {
  // body.graph 없으면 오류 발생해야 함 → 서버에서 400 반환
  const body = {};
  assert(!body.graph, 'graph 없어야 함');
});

// ─── 결과 ───────────────────────────────────────────────────────
console.log(`\n${'─'.repeat(40)}`);
console.log(`결과: ${pass + fail}개 중 ${pass}개 통과, ${fail}개 실패`);
if (fail === 0) console.log('🎉 Phase 3 모든 테스트 통과!');
process.exit(fail > 0 ? 1 : 0);

