/* ─── Reset & Base ─────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:         #0f0f13;
  --surface:    #1a1a24;
  --surface2:   #23232f;
  --border:     #2e2e3e;
  --accent:     #6366f1;
  --accent2:    #8b5cf6;
  --green:      #10b981;
  --yellow:     #f59e0b;
  --red:        #ef4444;
  --pink:       #ec4899;
  --text:       #e2e8f0;
  --text-muted: #64748b;
  --radius:     8px;
  --sidebar-w:  220px;
  --panel-w:    280px;
  --toolbar-h:  52px;
}

body { background: var(--bg); color: var(--text); font-family: system-ui, sans-serif; overflow: hidden; height: 100vh; }
#root { height: 100vh; display: flex; flex-direction: column; }

/* ─── Toolbar ───────────────────────────────────────────── */
.toolbar {
  height: var(--toolbar-h);
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 16px;
  gap: 12px;
  flex-shrink: 0;
  z-index: 10;
}

.toolbar-logo {
  font-weight: 700;
  font-size: 16px;
  background: linear-gradient(135deg, var(--accent), var(--pink));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-right: 8px;
}

.toolbar-sep { width: 1px; height: 24px; background: var(--border); }

.btn {
  padding: 6px 14px;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
  transition: opacity .15s, transform .1s;
}
.btn:active { transform: scale(0.96); }
.btn:disabled { opacity: .4; cursor: not-allowed; }

.btn-primary  { background: var(--accent);  color: #fff; }
.btn-success  { background: var(--green);   color: #fff; }
.btn-danger   { background: var(--red);     color: #fff; }
.btn-ghost    { background: var(--surface2); color: var(--text); border: 1px solid var(--border); }
.btn:not(:disabled):hover { opacity: .85; }

.toolbar-status {
  margin-left: auto;
  font-size: 12px;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 6px;
}
.status-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  background: var(--green);
  animation: pulse 2s infinite;
}
@keyframes pulse { 0%,100%{opacity:1} 50%{opacity:.4} }

/* ─── Layout ────────────────────────────────────────────── */
.workspace {
  flex: 1;
  display: flex;
  overflow: hidden;
}

/* ─── Node Palette (left) ───────────────────────────────── */
.palette {
  width: var(--sidebar-w);
  background: var(--surface);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  flex-shrink: 0;
}

.palette-title {
  padding: 12px 14px 8px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--text-muted);
}

.palette-group { margin-bottom: 4px; }
.palette-group-label {
  padding: 4px 14px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--text-muted);
  opacity: .7;
}

.palette-item {
  margin: 2px 8px;
  padding: 8px 10px;
  border-radius: 6px;
  cursor: grab;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  border: 1px solid transparent;
  transition: background .12s, border-color .12s;
  user-select: none;
}
.palette-item:hover { background: var(--surface2); border-color: var(--border); }
.palette-item:active { cursor: grabbing; }

.palette-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

/* ─── Canvas ────────────────────────────────────────────── */
.canvas-wrap {
  flex: 1;
  position: relative;
}

.react-flow__background { background: var(--bg); }
.react-flow__minimap    { background: var(--surface) !important; border-radius: var(--radius); }
.react-flow__controls   { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); }
.react-flow__controls-button {
  background: transparent !important;
  border-bottom-color: var(--border) !important;
  color: var(--text) !important;
}
.react-flow__controls-button svg { fill: var(--text) !important; }

/* ─── Custom Nodes ──────────────────────────────────────── */
.fw-node {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  min-width: 160px;
  box-shadow: 0 4px 20px rgba(0,0,0,.4);
  overflow: hidden;
  transition: box-shadow .15s;
}
.fw-node:hover        { box-shadow: 0 6px 28px rgba(0,0,0,.6); }
.fw-node.selected     { border-color: var(--accent); }

.fw-node-header {
  padding: 8px 12px;
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  font-weight: 600;
  border-bottom: 1px solid var(--border);
}
.fw-node-icon { font-size: 14px; }
.fw-node-label { flex: 1; }
.fw-node-type  { font-size: 10px; opacity: .5; text-transform: uppercase; }

.fw-node-body { padding: 8px 12px; font-size: 12px; }

.fw-prop-row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}
.fw-prop-label { color: var(--text-muted); min-width: 52px; font-size: 11px; }
.fw-prop-value {
  flex: 1;
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 3px 7px;
  color: var(--text);
  font-size: 11px;
  outline: none;
  width: 100%;
}
.fw-prop-value:focus { border-color: var(--accent); }

/* 포트 핸들 색상 */
.react-flow__handle { width: 10px; height: 10px; border-radius: 50%; border: 2px solid var(--bg); }
.react-flow__handle-left  { left: -5px; }
.react-flow__handle-right { right: -5px; }

/* ─── Properties Panel (right) ─────────────────────────── */
.props-panel {
  width: var(--panel-w);
  background: var(--surface);
  border-left: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  overflow-y: auto;
}

.props-panel-title {
  padding: 14px 16px 10px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  border-bottom: 1px solid var(--border);
  text-transform: uppercase;
  letter-spacing: .07em;
}

.props-empty {
  padding: 24px 16px;
  font-size: 13px;
  color: var(--text-muted);
  text-align: center;
}

.props-form { padding: 12px 14px; display: flex; flex-direction: column; gap: 10px; }
.props-field { display: flex; flex-direction: column; gap: 4px; }
.props-field label { font-size: 11px; color: var(--text-muted); text-transform: uppercase; letter-spacing: .06em; }
.props-field input, .props-field select, .props-field textarea {
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 6px 10px;
  color: var(--text);
  font-size: 13px;
  outline: none;
  width: 100%;
}
.props-field input:focus, .props-field select:focus { border-color: var(--accent); }
.props-field textarea { resize: vertical; min-height: 60px; font-family: monospace; }

.props-sep { height: 1px; background: var(--border); margin: 4px 0; }
.props-section-title { font-size: 11px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; }

/* ─── Preview Panel ─────────────────────────────────────── */
.preview-panel {
  position: fixed;
  right: calc(var(--panel-w) + 12px);
  bottom: 16px;
  width: 380px;
  height: 280px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: 0 8px 40px rgba(0,0,0,.6);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  z-index: 100;
  transition: transform .2s, opacity .2s;
}
.preview-panel.hidden { transform: translateY(20px); opacity: 0; pointer-events: none; }

.preview-header {
  padding: 8px 14px;
  font-size: 12px;
  font-weight: 600;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 8px;
}
.preview-header span { flex: 1; }
.preview-close { cursor: pointer; opacity: .5; font-size: 16px; }
.preview-close:hover { opacity: 1; }

.preview-frame {
  flex: 1;
  border: none;
  background: #fff;
}

/* ─── Toast ─────────────────────────────────────────────── */
.toast-wrap {
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 999;
  pointer-events: none;
}
.toast {
  background: var(--surface2);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 10px 18px;
  border-radius: 8px;
  font-size: 13px;
  box-shadow: 0 4px 20px rgba(0,0,0,.5);
  animation: slideUp .2s ease;
}
.toast.error  { border-color: var(--red);   color: var(--red); }
.toast.success { border-color: var(--green); color: var(--green); }
@keyframes slideUp { from { transform: translateY(10px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }

/* ─── Edge ───────────────────────────────────────────────── */
.react-flow__edge-path { stroke-width: 2; }

