toolUseResult.originalFile:
/**
 * FreeWire - 백엔드 API 서버
 * POST /compile  → 그래프 JSON → .free 코드
 * POST /execute  → 그래프 JSON → HTML/CSS/JS
 * GET  /preview/:id → 브라우저 미리보기
 * GET  /health
 */

const http = require('http');
const { Graph }          = require('../core/graph');
const { GraphCompiler }  = require('../compiler/graph-compiler');
const { FreeExecutor }   = require('./free-executor');

const PORT = process.env.FREEWIRE_PORT || 4010;

const compiler = new GraphCompiler();
const executor = new FreeExecutor();

// 미리보기 캐시 { id → { html, css, js, createdAt } }
const previewCache = new Map();

// ─── 라우터 ─────────────────────────────────────────────────────
const ROUTES = {
  'GET /health':       handleHealth,
  'GET /api/nodes':    handleNodeTypes,
  'POST /api/compile': handleCompile,
  'POST /api/execute': handleExecute,
  'POST /api/preview': handlePreviewCreate,
};

function router(req, res) {
  const key = `${req.method} ${req.url.split('?')[0]}`;

  // GET /preview/:id
  if (req.method === 'GET' && req.url.startsWith('/preview/')) {
    return handlePreviewGet(req, res);
  }

  const handler = ROUTES[key];
  if (handler) return handler(req, res);

  send(res, 404, { error: `라우트 없음: ${key}` });
}

// ─── 핸들러 ─────────────────────────────────────────────────────

function handleHealth(req, res) {
  send(res, 200, {
    status: 'ok',
    service: 'FreeWire API',
    version: '0.1.0',
    uptime: process.uptime().toFixed(1) + 's',
  });
}

function handleNodeTypes(req, res) {
  const { NODE_TYPE_DEFS } = require('../core/node-types-index');
  send(res, 200, { nodeTypes: NODE_TYPE_DEFS });
}

async function handleCompile(req, res) {
  let body;
  try { body = await readBody(req); }
  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }

  const { graph } = body;
  if (!graph) return send(res, 400, { error: 'body.graph 필수' });

  try {
    const result = compiler.compile(graph);
    send(res, 200, {
      code:     result.code,
      errors:   result.errors,
      warnings: result.warnings,
    });
  } catch (e) {
    send(res, 500, { error: '컴파일 실패: ' + e.message });
  }
}

async function handleExecute(req, res) {
  let body;
  try { body = await readBody(req); }
  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }

  const { graph } = body;
  if (!graph) return send(res, 400, { error: 'body.graph 필수' });

  try {
    const compiled = compiler.compile(graph);
    if (compiled.errors.length > 0) {
      return send(res, 422, { error: '컴파일 오류', details: compiled.errors });
    }
    const output = executor.execute(compiled.code, graph);
    send(res, 200, output);
  } catch (e) {
    send(res, 500, { error: '실행 실패: ' + e.message });
  }
}

async function handlePreviewCreate(req, res) {
  let body;
  try { body = await readBody(req); }
  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }

  const { graph } = body;
  if (!graph) return send(res, 400, { error: 'body.graph 필수' });

  try {
    const compiled = compiler.compile(graph);
    if (compiled.errors.length > 0) {
      return send(res, 422, { error: '컴파일 오류', details: compiled.errors });
    }
    const output = executor.execute(compiled.code, graph);
    const id     = `preview-${Date.now()}`;
    previewCache.set(id, { ...output, createdAt: Date.now() });

    // 캐시 1시간 TTL
    setTimeout(() => previewCache.delete(id), 3600_000);

    send(res, 201, { previewId: id, url: `/preview/${id}` });
  } catch (e) {
    send(res, 500, { error: '미리보기 생성 실패: ' + e.message });
  }
}

function handlePreviewGet(req, res) {
  const id = req.url.replace('/preview/', '').split('?')[0];
  const preview = previewCache.get(id);

  if (!preview) {
    res.writeHead(404, { 'Content-Type': 'text/html' });
    res.end('<h1>미리보기 없음 (만료되었거나 잘못된 ID)</h1>');
    return;
  }

  const html = buildPreviewHtml(preview);
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(html);
}

// ─── 유틸 ────────────────────────────────────────────────────────

function buildPreviewHtml({ html, css, js }) {
  return `<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>FreeWire 미리보기</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: system-ui, sans-serif; padding: 24px; background: #f9fafb; }
    .freewire-badge {
      position: fixed; bottom: 12px; right: 12px;
      background: #6366f1; color: white;
      padding: 4px 10px; border-radius: 999px;
      font-size: 12px; opacity: 0.85;
    }
    ${css || ''}
  </style>
</head>
<body>
  <div id="app">${html || '<p style="color:#999">내용 없음</p>'}</div>
  <div class="freewire-badge">⚡ FreeWire</div>
  <script>${js || ''}</script>
</body>
</html>`;
}

function send(res, status, data) {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    'Content-Type':  'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'Content-Type',
  });
  res.end(body);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', chunk => { data += chunk; if (data.length > 1_000_000) reject(new Error('너무 큰 요청')); });
    req.on('end',  () => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } });
    req.on('error', reject);
  });
}

// ─── 서버 시작 ───────────────────────────────────────────────────
const server = http.createServer((req, res) => {
  if (req.method === 'OPTIONS') {
    res.writeHead(204, { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'Content-Type', 'Access-Control-Allow-Methods': 'GET,POST' });
    return res.end();
  }
  router(req, res);
});

if (require.main === module) {
  server.listen(PORT, () => {
    console.log(`\n⚡ FreeWire API 서버 시작`);
    console.log(`   http://localhost:${PORT}/health`);
    console.log(`   POST http://localhost:${PORT}/api/compile`);
    console.log(`   POST http://localhost:${PORT}/api/execute`);
    console.log(`   POST http://localhost:${PORT}/api/preview\n`);
  });
}

module.exports = { server, previewCache };

