/* ─── Edge ───────────────────────────────────────────────── */
.react-flow__edge-path { stroke-width: 2; }

/* ─── AI Button ─────────────────────────────────────────── */
.btn-ai {
  background: linear-gradient(135deg, #6366f1, #ec4899);
  color: #fff;
  font-weight: 600;
}
.btn-ai:not(:disabled):hover { opacity: .85; }

/* ─── AI Panel ──────────────────────────────────────────── */
.ai-panel {
  position: fixed;
  top: calc(var(--toolbar-h) + 12px);
  left: calc(var(--sidebar-w) + 16px);
  width: 340px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: 0 8px 40px rgba(0,0,0,.6);
  z-index: 200;
  overflow: hidden;
  animation: slideDown .18s ease;
}
@keyframes slideDown { from { transform:translateY(-8px); opacity:0; } to { transform:translateY(0); opacity:1; } }

.ai-panel-header {
  padding: 10px 14px;
  font-size: 13px;
  font-weight: 600;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(135deg, rgba(99,102,241,.15), rgba(236,72,153,.15));
}

.ai-panel-body {
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ai-hint { font-size: 12px; color: var(--text-muted); }

.ai-examples {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.ai-example-chip {
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11px;
  background: var(--surface2);
  border: 1px solid var(--border);
  cursor: pointer;
  transition: border-color .12s, background .12s;
  color: var(--text);
}
.ai-example-chip:hover {
  border-color: var(--accent);
  background: rgba(99,102,241,.15);
}

.ai-input {
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 8px 12px;
  color: var(--text);
  font-size: 13px;
  outline: none;
  width: 100%;
  font-family: inherit;
  resize: none;
}
.ai-input:focus { border-color: var(--accent); }

