/**
 * FreeWire Phase 5 - AI 노드 생성기 테스트
 */

const { generateNodes } = require('../api/ai-generator');

let pass = 0, fail = 0;

function test(name, fn) {
  try { fn(); console.log(`  ✅ ${name}`); pass++; }
  catch (e) { console.log(`  ❌ ${name}: ${e.message}`); fail++; }
}
async function testAsync(name, fn) {
  try { await fn(); console.log(`  ✅ ${name}`); pass++; }
  catch (e) { console.log(`  ❌ ${name}: ${e.message}`); fail++; }
}
function assert(cond, msg) { if (!cond) throw new Error(msg || '실패'); }

// ─── 패턴 매칭 테스트 ────────────────────────────────────────────
console.log('\n[1] 패턴 매칭 - 카운터');
await testAsync('카운터 노드 생성', async () => {
  const r = await generateNodes('카운터 앱 만들어줘');
  assert(r.source === 'pattern', 'pattern 소스');
  assert(Array.isArray(r.nodes),  'nodes 배열');
  assert(Array.isArray(r.edges),  'edges 배열');
  assert(r.nodes.length > 0,      '노드 있음');
  assert(r.nodes.some(n => n.type === 'data' && n.subtype === 'state'), 'state 노드');
  assert(r.nodes.some(n => n.type === 'component' && n.subtype === 'button'), 'button 노드');
  assert(r.nodes.some(n => n.type === 'logic' && n.subtype === 'function'), 'function 노드');
});

await testAsync('counter 영문 키워드', async () => {
  const r = await generateNodes('counter app');
  assert(r.source === 'pattern');
  assert(r.nodes.some(n => n.props?.name === 'count'), 'count state');
});

await testAsync('숫자 증가 키워드', async () => {
  const r = await generateNodes('숫자 증가하는 앱');
  assert(r.source === 'pattern');
  assert(r.nodes.length > 3);
});

console.log('\n[2] 패턴 매칭 - 로그인');
await testAsync('로그인 폼 생성', async () => {
  const r = await generateNodes('로그인 폼 만들어줘');
  assert(r.source === 'pattern');
  assert(r.nodes.some(n => n.subtype === 'input'), 'input 노드');
  assert(r.nodes.some(n => n.subtype === 'card'),  'card 노드');
  assert(r.nodes.some(n => n.props?.dataType === 'string'), 'string 상태');
});

await testAsync('이메일 키워드', async () => {
  const r = await generateNodes('이메일 비밀번호 입력');
  assert(r.source === 'pattern');
});

console.log('\n[3] 패턴 매칭 - 투두');
await testAsync('투두 리스트 생성', async () => {
  const r = await generateNodes('투두 리스트 만들어줘');
  assert(r.source === 'pattern');
  assert(r.nodes.some(n => n.subtype === 'array'),  'array 노드');
  assert(r.nodes.some(n => n.subtype === 'map'),    'map 노드');
  assert(r.nodes.some(n => n.subtype === 'list'),   'list 컴포넌트');
});

await testAsync('할일 키워드', async () => {
  const r = await generateNodes('할 일 관리 앱');
  assert(r.source === 'pattern');
});

console.log('\n[4] 패턴 매칭 - 계산기');
await testAsync('계산기 생성', async () => {
  const r = await generateNodes('계산기 만들어줘');
  assert(r.source === 'pattern');
  assert(r.nodes.filter(n => n.subtype === 'function').length >= 2, '함수 2개 이상');
  assert(r.nodes.filter(n => n.subtype === 'input').length >= 2, '입력 2개 이상');
  assert(r.nodes.some(n => n.props?.body?.includes('+')), '덧셈 함수');
});

console.log('\n[5] 패턴 매칭 - 프로필');
await testAsync('프로필 카드 생성', async () => {
  const r = await generateNodes('프로필 카드 만들어줘');
  assert(r.source === 'pattern');
  assert(r.nodes.some(n => n.subtype === 'card'), 'card 노드');
  assert(r.nodes.some(n => n.subtype === 'string'), 'string 데이터');
});

console.log('\n[6] 폴백 - 패턴 미일치');
await testAsync('미일치 프롬프트 → 폴백', async () => {
  const r = await generateNodes('완전히 새로운 앱 xyz123');
  assert(r.source === 'fallback', `source: ${r.source}`);
  assert(r.nodes.length > 0, '기본 노드 있음');
  assert(r.nodes.some(n => n.type === 'component'), 'component 포함');
});

await testAsync('폴백 노드 구조 유효성', async () => {
  const r = await generateNodes('알 수 없는 앱');
  r.nodes.forEach(n => {
    assert(n.id,       `id 없음: ${JSON.stringify(n)}`);
    assert(n.type,     `type 없음: ${n.id}`);
    assert(n.subtype,  `subtype 없음: ${n.id}`);
    assert(n.position, `position 없음: ${n.id}`);
    assert(n.props,    `props 없음: ${n.id}`);
  });
});

console.log('\n[7] 노드 구조 검증');
await testAsync('모든 노드에 position 포함', async () => {
  const r = await generateNodes('카운터');
  r.nodes.forEach(n => {
    assert(typeof n.position.x === 'number', `x 없음: ${n.id}`);
    assert(typeof n.position.y === 'number', `y 없음: ${n.id}`);
  });
});

await testAsync('엣지 source/target 유효성', async () => {
  const r = await generateNodes('카운터 앱');
  const ids = new Set(r.nodes.map(n => n.id));
  r.edges.forEach(e => {
    assert(ids.has(e.source), `source 없음: ${e.source}`);
    assert(ids.has(e.target), `target 없음: ${e.target}`);
  });
});

await testAsync('모든 노드에 icon 포함', async () => {
  const r = await generateNodes('투두 리스트');
  r.nodes.forEach(n => assert(n.icon, `icon 없음: ${n.id}`));
});

await testAsync('description 포함', async () => {
  const r = await generateNodes('로그인 폼');
  assert(typeof r.description === 'string', 'description 문자열');
  assert(r.description.length > 0, 'description 내용 있음');
});

console.log('\n[8] 레이아웃 규칙 검증');
await testAsync('data 노드 x < logic 노드 x', async () => {
  const r = await generateNodes('카운터 앱');
  const dataNodes  = r.nodes.filter(n => n.type === 'data');
  const logicNodes = r.nodes.filter(n => n.type === 'logic');
  if (dataNodes.length > 0 && logicNodes.length > 0) {
    const maxDataX  = Math.max(...dataNodes.map(n => n.position.x));
    const minLogicX = Math.min(...logicNodes.map(n => n.position.x));
    assert(maxDataX < minLogicX, `data(${maxDataX}) < logic(${minLogicX})`);
  }
});

await testAsync('logic 노드 x < component 노드 x', async () => {
  const r = await generateNodes('카운터 앱');
  const logicNodes  = r.nodes.filter(n => n.type === 'logic');
  const compNodes   = r.nodes.filter(n => n.type === 'component');
  if (logicNodes.length > 0 && compNodes.length > 0) {
    const maxLogicX = Math.max(...logicNodes.map(n => n.position.x));
    const minCompX  = Math.min(...compNodes.map(n => n.position.x));
    assert(maxLogicX < minCompX, `logic(${maxLogicX}) < component(${minCompX})`);
  }
});

// ─── 결과 ───────────────────────────────────────────────────────
console.log(`\n${'─'.repeat(40)}`);
console.log(`결과: ${pass + fail}개 중 ${pass}개 통과, ${fail}개 실패`);
if (fail === 0) console.log('🎉 Phase 5 모든 테스트 통과!');
process.exit(fail > 0 ? 1 : 0);

