  assert(r.nodes.filter(n => n.subtype === 'function').length >= 2, '함수 2개 이상');
  assert(r.nodes.filter(n => n.subtype === 'input').length >= 2, '입력 2개 이상');
  assert(r.nodes.some(n => n.props?.body?.includes('+')), '덧셈 함수');
});

