  const r = await generateNodes('완전히 새로운 앱 xyz123');
  assert(r.source === 'fallback', `source: ${r.source}`);
  assert(r.nodes.length > 0, '기본 노드 있음');
  assert(r.nodes.some(n => n.type === 'component'), 'component 포함');
});

await testAsync('폴백 노드 구조 유효성', async () => {
  const r = await generateNodes('알 수 없는 앱');
  r.nodes.forEach(n => {
    assert(n.id,       `id 없음: ${JSON.stringify(n)}`);
    assert(n.type,     `type 없음: ${n.id}`);
    assert(n.subtype,  `subtype 없음: ${n.id}`);
    assert(n.position, `position 없음: ${n.id}`);
    assert(n.props,    `props 없음: ${n.id}`);
  });
});

console.log('\n[7] 노드 구조 검증');
await testAsync('모든 노드에 position 포함', async () => {
  const r = await generateNodes('카운터');
  r.nodes.forEach(n => {
    assert(typeof n.position.x === 'number', `x 없음: ${n.id}`);
    assert(typeof n.position.y === 'number', `y 없음: ${n.id}`);
  });
});

await testAsync('엣지 source/target 유효성', async () => {
  const r = await generateNodes('카운터 앱');
  const ids = new Set(r.nodes.map(n => n.id));
  r.edges.forEach(e => {
    assert(ids.has(e.source), `source 없음: ${e.source}`);
