  });
});

await testAsync('모든 노드에 icon 포함', async () => {
  const r = await generateNodes('투두 리스트');
  r.nodes.forEach(n => assert(n.icon, `icon 없음: ${n.id}`));
});

await testAsync('description 포함', async () => {
