});

console.log('\n[8] 레이아웃 규칙 검증');
await testAsync('data 노드 x < logic 노드 x', async () => {
  const r = await generateNodes('카운터 앱');
  const dataNodes  = r.nodes.filter(n => n.type === 'data');
  const logicNodes = r.nodes.filter(n => n.type === 'logic');
  if (dataNodes.length > 0 && logicNodes.length > 0) {
    const maxDataX  = Math.max(...dataNodes.map(n => n.position.x));
    const minLogicX = Math.min(...logicNodes.map(n => n.position.x));
    assert(maxDataX < minLogicX, `data(${maxDataX}) < logic(${minLogicX})`);
  }
});

await testAsync('logic 노드 x < component 노드 x', async () => {
  const r = await generateNodes('카운터 앱');
  const logicNodes  = r.nodes.filter(n => n.type === 'logic');
