/* FreeWire REPL - 브라우저 실시간 실행기 */
'use strict';

const executor = new BrowserExecutor();
let activeTab  = 'preview';
let runCount   = 0;

// ─── 예제 코드 ──────────────────────────────────────────────────
const EXAMPLES = {
  counter: `component Counter {
  script {
    let count = 0;
    function set_count(v) { count = v; }
    function increment() { set_count(count + 1); }
    function decrement() { set_count(count - 1); }
    function reset() { set_count(0); }
  }
  style {
    .counter-wrap {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 16px;
      padding: 32px;
    }
    .count-display {
      font-size: 64px;
      font-weight: 700;
      color: #6366f1;
    }
    .btn-row {
      display: flex;
      gap: 8px;
    }
  }
  markup {
    <div class="counter-wrap">
      <div class="count-display">{{count}}</div>
      <div class="btn-row">
        <button class="primary" data-fw-action="decrement">-1</button>
        <button class="secondary" data-fw-action="reset">초기화</button>
        <button class="primary" data-fw-action="increment">+1</button>
      </div>
    </div>
  }
}`,

  card: `component ProfileCard {
  style {
    .profile {
      max-width: 320px;
      margin: 24px auto;
    }
    .avatar {
      width: 72px; height: 72px;
      border-radius: 50%;
      background: linear-gradient(135deg, #6366f1, #ec4899);
      display: flex; align-items: center; justify-content: center;
      font-size: 28px; margin: 0 auto 16px;
    }
    .name {
      text-align: center;
      font-size: 20px; font-weight: 700;
      color: #1f2937; margin-bottom: 4px;
    }
    .role {
      text-align: center;
      color: #6366f1; font-size: 14px; margin-bottom: 16px;
    }
    .btn-row {
      display: flex; gap: 8px; justify-content: center;
    }
  }
  markup {
    <div class="profile card">
      <div class="avatar">👤</div>
      <div class="name">김개발</div>
      <div class="role">FreeLang 개발자</div>
      <div class="btn-row">
        <button class="primary">팔로우</button>
        <button class="ghost">메시지</button>
      </div>
    </div>
  }
}`,

  form: `component LoginForm {
  script {
    let email = "";
    let password = "";
    function set_email(v) { email = v; }
    function set_password(v) { password = v; }
    function handleLogin() {
      if (!email || !password) {
        alert("이메일과 비밀번호를 입력하세요");
        return;
      }
      alert("로그인 시도: " + email);
    }
  }
  style {
    .form-wrap {
      max-width: 360px; margin: 32px auto;
      display: flex; flex-direction: column; gap: 16px;
    }
    .form-title {
      font-size: 22px; font-weight: 700;
      text-align: center; color: #1f2937;
      margin-bottom: 8px;
    }
    .form-label {
      font-size: 13px; color: #6b7280;
      margin-bottom: 4px; display: block;
    }
    .field { display: flex; flex-direction: column; }
  }
  markup {
    <div class="form-wrap card">
      <div class="form-title">🔐 로그인</div>
      <div class="field">
        <label class="form-label">이메일</label>
        <input type="email" placeholder="you@example.com" />
      </div>
      <div class="field">
        <label class="form-label">비밀번호</label>
        <input type="password" placeholder="비밀번호 입력" />
      </div>
      <button class="primary" data-fw-action="handleLogin">로그인</button>
    </div>
  }
}`,

  list: `component TodoList {
  script {
    let todos = ["FreeLang 배우기", "FreeWire 만들기", "WASM 추가하기"];
    let nextTodo = "";
    function set_nextTodo(v) { nextTodo = v; }
    function addTodo() {
      if (!nextTodo.trim()) return;
      todos = [...todos, nextTodo];
      set_nextTodo("");
      __fw_update();
      renderTodos();
    }
    function renderTodos() {
      var list = document.getElementById("todo-list");
      if (!list) return;
      list.innerHTML = todos.map(function(t, i) {
        return '<li style="padding:8px 0;border-bottom:1px solid #e5e7eb;display:flex;gap:8px;align-items:center">' +
               '<span style="color:#6366f1">✓</span>' + t + '</li>';
      }).join("");
    }
    document.addEventListener("DOMContentLoaded", function() { renderTodos(); });
  }
  style {
    .todo-wrap {
      max-width: 400px; margin: 24px auto;
      display: flex; flex-direction: column; gap: 16px;
    }
    .todo-title { font-size: 20px; font-weight: 700; color: #1f2937; }
    .input-row  { display: flex; gap: 8px; }
    .input-row input { flex: 1; }
    ul { list-style: none; }
  }
  markup {
    <div class="todo-wrap card">
      <div class="todo-title">📋 할 일 목록</div>
      <div class="input-row">
        <input type="text" placeholder="새 할 일..." id="todo-input" />
        <button class="primary" data-fw-action="addTodo">추가</button>
      </div>
      <ul id="todo-list"></ul>
    </div>
  }
}`,

  animation: `component AnimCard {
  style {
    .anim-wrap {
      display: flex; flex-direction: column;
      align-items: center; gap: 24px; padding: 32px;
    }
    .pulse-box {
      width: 80px; height: 80px;
      background: linear-gradient(135deg, #6366f1, #ec4899);
      border-radius: 16px;
      animation: pulse-anim 1.5s ease-in-out infinite;
      display: flex; align-items: center; justify-content: center;
      font-size: 32px;
    }
    @keyframes pulse-anim {
      0%, 100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(99,102,241,.4); }
      50%       { transform: scale(1.1); box-shadow: 0 0 0 16px rgba(99,102,241,0); }
    }
    .slide-in {
      animation: slide-in 0.5s ease-out;
    }
    @keyframes slide-in {
      from { transform: translateX(-30px); opacity: 0; }
      to   { transform: translateX(0);     opacity: 1; }
    }
    .anim-title { font-size: 22px; font-weight: 700; color: #1f2937; }
    .anim-desc  { color: #6b7280; text-align: center; max-width: 280px; }
  }
  markup {
    <div class="anim-wrap">
      <div class="pulse-box">⚡</div>
      <div class="anim-title slide-in">FreeWire 애니메이션</div>
      <p class="anim-desc slide-in">
        FreeLang Light의 CSS 애니메이션 엔진으로<br>
        자동 생성된 인터랙티브 컴포넌트
      </p>
      <button class="primary">체험하기</button>
    </div>
  }
}`,
};

// ─── 탭 전환 ─────────────────────────────────────────────────────
function switchTab(name) {
  activeTab = name;
  document.querySelectorAll('.tab').forEach((t, i) => {
    const names = ['preview','html','css','js','console'];
    t.classList.toggle('active', names[i] === name);
  });
  document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));
  document.getElementById(`tab-${name}`)?.classList.add('active');
}

// ─── 코드 실행 ───────────────────────────────────────────────────
function runCode() {
  const code = document.getElementById('code-editor').value.trim();
  if (!code) return addConsole('코드를 입력하세요', 'warn');

  const t0 = Date.now();
  addConsole(`▶ 실행 #${++runCount}...`, 'info');

  try {
    const result = executor.execute(code);
    const html   = executor.buildPreviewHTML(result);

    // 미리보기 업데이트
    const frame = document.getElementById('preview-frame');
    frame.srcdoc = html;

    // 코드 출력
    document.getElementById('out-html').textContent = result.html || '(없음)';
    document.getElementById('out-css').textContent  = result.css  || '(없음)';
    document.getElementById('out-js').textContent   = result.js   || '(없음)';

    // 통계 업데이트
    const elapsed = Date.now() - t0;
    document.getElementById('stat-status').innerHTML = `<span class="stat-ok">✓ 성공</span>`;
    document.getElementById('stat-html').textContent = `HTML: ${result.stats.htmlBytes}B`;
    document.getElementById('stat-css').textContent  = `CSS: ${result.stats.cssBytes}B`;
    document.getElementById('stat-js').textContent   = `JS: ${result.stats.jsBytes}B`;
    document.getElementById('stat-time').textContent = `${elapsed}ms`;

    addConsole(`✓ ${result.name} 컴파일 완료 (${elapsed}ms) HTML:${result.stats.htmlBytes}B CSS:${result.stats.cssBytes}B JS:${result.stats.jsBytes}B`, 'ok');
    switchTab('preview');

  } catch (e) {
    document.getElementById('stat-status').innerHTML = `<span class="stat-err">✗ 오류</span>`;
    addConsole('오류: ' + e.message, 'error');
    console.error(e);
  }
}

// ─── 콘솔 출력 ───────────────────────────────────────────────────
function addConsole(msg, type = 'info') {
  const el   = document.getElementById('out-console');
  const line = document.createElement('div');
  line.className = `console-line ${type}`;
  const time = new Date().toLocaleTimeString('ko', { hour12: false });
  line.innerHTML = `<span class="console-prompt">[${time}]</span>${escapeHtml(msg)}`;
  el.appendChild(line);
  el.scrollTop = el.scrollHeight;
}

function escapeHtml(s) {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

// ─── 예제 로드 ───────────────────────────────────────────────────
function loadExample(name) {
  const code = EXAMPLES[name];
  if (!code) return;
  document.getElementById('code-editor').value = code;
  addConsole(`예제 로드: ${name}`, 'info');
  runCode();
}

// ─── 초기화 ──────────────────────────────────────────────────────
function clearEditor() {
  document.getElementById('code-editor').value = '';
  document.getElementById('preview-frame').srcdoc = '';
  document.getElementById('out-html').textContent = '';
  document.getElementById('out-css').textContent  = '';
  document.getElementById('out-js').textContent   = '';
  document.getElementById('stat-status').textContent = '준비';
  addConsole('에디터 초기화됨', 'info');
}

// ─── 키보드 단축키 ────────────────────────────────────────────────
document.getElementById('code-editor').addEventListener('keydown', e => {
  // Ctrl+Enter: 실행
  if (e.ctrlKey && e.key === 'Enter') { e.preventDefault(); runCode(); }
  // Tab: 들여쓰기
  if (e.key === 'Tab') {
    e.preventDefault();
    const el  = e.target;
    const s   = el.selectionStart;
    el.value  = el.value.slice(0, s) + '  ' + el.value.slice(el.selectionEnd);
    el.selectionStart = el.selectionEnd = s + 2;
  }
});

// ─── 초기 예제 로드 ──────────────────────────────────────────────
window.addEventListener('DOMContentLoaded', () => {
  addConsole('FreeWire REPL 시작 — Ctrl+Enter로 실행', 'ok');
  loadExample('counter');
});

