    console.log(`   POST http://localhost:${PORT}/api/compile`);
    console.log(`   POST http://localhost:${PORT}/api/execute`);
    console.log(`   POST http://localhost:${PORT}/api/preview\n`);
  });
}

module.exports = { server, previewCache };

/* FreeWire Editor - React Flow 기반 노드 에디터 */
'use strict';

const { createElement: h, useState, useCallback, useRef, useEffect, useReducer } = React;
const { createRoot } = ReactDOM;
const RF = window.ReactFlow || window.ReactFlowRenderer;
const {
  ReactFlow, Background, Controls, MiniMap,
  addEdge, applyNodeChanges, applyEdgeChanges,
  Handle, Position,
} = RF;

const API = 'http://localhost:4010/api';

// ─── 노드 팔레트 정의 ────────────────────────────────────────────
const PALETTE = [
  { category: 'UI 컴포넌트', color: '#6366f1', items: [
    { type: 'fw-component', subtype: 'button',    label: '버튼',      icon: '🔘', defaultProps: { label: '클릭', variant: 'primary' } },
    { type: 'fw-component', subtype: 'input',     label: '입력창',    icon: '✏️', defaultProps: { placeholder: '입력', type: 'text' } },
    { type: 'fw-component', subtype: 'text',      label: '텍스트',    icon: '📝', defaultProps: { content: '텍스트', tag: 'p', color: '#e2e8f0' } },
    { type: 'fw-component', subtype: 'card',      label: '카드',      icon: '🃏', defaultProps: { title: '제목', content: '내용', variant: 'default' } },
    { type: 'fw-component', subtype: 'container', label: '컨테이너',  icon: '📦', defaultProps: { direction: 'column', gap: '8px', padding: '16px' } },
  ]},
  { category: '데이터', color: '#8b5cf6', items: [
    { type: 'fw-data', subtype: 'state',   label: 'State',   icon: '💾', defaultProps: { name: 'count', value: '0',     dataType: 'number' } },
    { type: 'fw-data', subtype: 'props',   label: 'Props',   icon: '📨', defaultProps: { name: 'title', value: '',      dataType: 'string' } },
    { type: 'fw-data', subtype: 'number',  label: '숫자',    icon: '🔢', defaultProps: { name: 'num',   value: '0',     dataType: 'number' } },
    { type: 'fw-data', subtype: 'string',  label: '문자열',  icon: '🔤', defaultProps: { name: 'str',   value: 'Hello', dataType: 'string' } },
    { type: 'fw-data', subtype: 'array',   label: '배열',    icon: '📋', defaultProps: { name: 'list',  value: '[]',    dataType: 'array'  } },
  ]},
  { category: '로직', color: '#f59e0b', items: [
    { type: 'fw-logic', subtype: 'if',       label: '조건(if)',    icon: '🔀', defaultProps: { condition: 'x > 0' } },
    { type: 'fw-logic', subtype: 'function', label: '함수',        icon: '⚙️', defaultProps: { name: 'handler', params: '', body: 'return null;' } },
    { type: 'fw-logic', subtype: 'map',      label: 'Map',         icon: '🗺️', defaultProps: { itemName: 'item', expression: 'item' } },
    { type: 'fw-logic', subtype: 'filter',   label: 'Filter',      icon: '🔍', defaultProps: { itemName: 'item', condition: 'item != null' } },
  ]},
];

const TYPE_COLORS = { 'fw-component': '#6366f1', 'fw-data': '#8b5cf6', 'fw-logic': '#f59e0b' };
const TYPE_LABELS = { 'fw-component': 'UI', 'fw-data': 'DATA', 'fw-logic': 'LOGIC' };

// ─── 커스텀 노드 ─────────────────────────────────────────────────
function FWNode({ data, selected }) {
  const color = TYPE_COLORS[data.nodeType] || '#6366f1';
  const typeLabel = TYPE_LABELS[data.nodeType] || '';

  const propEntries = Object.entries(data.props || {}).slice(0, 3);

  return h('div', { className: `fw-node${selected ? ' selected' : ''}`,
                    style: { borderTopColor: color, borderTopWidth: 3 } },
    // 입력 핸들
    h(Handle, { type: 'target', position: Position.Left,
                style: { background: color } }),

    // 헤더
    h('div', { className: 'fw-node-header' },
      h('span', { className: 'fw-node-icon' }, data.icon || '⬡'),
      h('span', { className: 'fw-node-label' }, data.label),
      h('span', { className: 'fw-node-type', style: { color } }, typeLabel),
    ),

    // 바디: props 미리보기
    h('div', { className: 'fw-node-body' },
      ...propEntries.map(([k, v]) =>
        h('div', { className: 'fw-prop-row', key: k },
          h('span', { className: 'fw-prop-label' }, k),
          h('input', {
            className: 'fw-prop-value',
            value: String(v),
            onChange: (e) => data.onPropChange && data.onPropChange(k, e.target.value),
          }),
        )
      ),
    ),

    // 출력 핸들
    h(Handle, { type: 'source', position: Position.Right,
                style: { background: color } }),
  );
}

const NODE_TYPES = { 'fw-component': FWNode, 'fw-data': FWNode, 'fw-logic': FWNode };

// ─── 메인 에디터 ─────────────────────────────────────────────────
let nodeIdSeq = 1;
function genId() { return `node-${nodeIdSeq++}`; }

function App() {
  const [nodes, setNodes] = useState([]);
  const [edges, setEdges] = useState([]);
  const [selected, setSelected] = useState(null);
  const [preview, setPreview] = useState(null);
  const [status, setStatus] = useState('준비');
  const [toasts, setToasts] = useState([]);
  const [aiPrompt, setAiPrompt] = useState('');
  const [aiLoading, setAiLoading] = useState(false);
  const [showAi, setShowAi] = useState(false);
  const canvasRef = useRef(null);

  // ── 토스트 ────────────────────────────────────────────────────
  function toast(msg, type = '') {
    const id = Date.now();
    setToasts(t => [...t, { id, msg, type }]);
    setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 3000);
  }

  // ── props 변경 콜백 ───────────────────────────────────────────
  const updateProp = useCallback((nodeId, key, val) => {
    setNodes(ns => ns.map(n =>
      n.id === nodeId
        ? { ...n, data: { ...n.data, props: { ...n.data.props, [key]: val } } }
        : n
    ));
  }, []);

  // ── React Flow 이벤트 ─────────────────────────────────────────
  const onNodesChange = useCallback(changes => setNodes(ns => applyNodeChanges(changes, ns)), []);
  const onEdgesChange = useCallback(changes => setEdges(es => applyEdgeChanges(changes, es)), []);
  const onConnect     = useCallback(params  => setEdges(es => addEdge({ ...params, animated: true, style: { stroke: '#6366f1' } }, es)), []);

  const onNodeClick = useCallback((_, node) => setSelected(node), []);
  const onPaneClick = useCallback(() => setSelected(null), []);

  // ── 팔레트 드래그 ─────────────────────────────────────────────
  function onDragStart(e, item) {
    e.dataTransfer.setData('fw-item', JSON.stringify(item));
    e.dataTransfer.effectAllowed = 'move';
  }

  function onDrop(e) {
    e.preventDefault();
    const raw = e.dataTransfer.getData('fw-item');
    if (!raw) return;
    const item = JSON.parse(raw);

    const rect = canvasRef.current?.getBoundingClientRect() || { left: 0, top: 0 };
    const pos  = { x: e.clientX - rect.left - 80, y: e.clientY - rect.top - 40 };

    const id = genId();
    const newNode = {
      id,
      type: item.type,
      position: pos,
      data: {
        nodeType:     item.type,
        subtype:      item.subtype,
        label:        item.label,
        icon:         item.icon,
        props:        { ...item.defaultProps },
        onPropChange: (k, v) => updateProp(id, k, v),
      },
    };
    setNodes(ns => [...ns, newNode]);
    toast(`"${item.label}" 노드 추가됨`, 'success');
  }

  function onDragOver(e) { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; }

  // ── 그래프 → API JSON 변환 ────────────────────────────────────
  function buildGraphJSON() {
    return {
      id:    'freewire-graph',
      nodes: nodes.map(n => ({
        id:            n.id,
        type:          n.data.subtype === 'state' || n.data.subtype === 'props' || ['number','string','array'].includes(n.data.subtype)
                         ? 'data'
                         : n.data.nodeType === 'fw-logic' ? 'logic' : 'component',
        componentType: n.data.subtype,
        logicType:     n.data.subtype,
        dataType:      n.data.subtype,
        inputs:        [],
        outputs:       [],
        props:         n.data.props,
      })),
      edges: edges.map(e => ({
        id:   e.id,
        from: { nodeId: e.source, portId: e.sourceHandle || 'out', portType: 'any' },
        to:   { nodeId: e.target, portId: e.targetHandle || 'in',  portType: 'any' },
      })),
    };
  }

  // ── 컴파일 ───────────────────────────────────────────────────
  async function handleCompile() {
    if (nodes.length === 0) return toast('노드가 없습니다.', 'error');
    setStatus('컴파일 중...');
    try {
      const res  = await fetch(`${API}/compile`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ graph: buildGraphJSON() }),
      });
      const data = await res.json();
      if (data.error) throw new Error(data.error);
      toast('✅ 컴파일 성공!', 'success');
      setStatus('컴파일 완료');
      console.log('[FreeWire] 생성된 .free 코드:\n', data.code);
    } catch (e) {
      toast('컴파일 실패: ' + e.message, 'error');
      setStatus('오류');
    }
  }

  // ── 실행 & 미리보기 ───────────────────────────────────────────
  async function handlePreview() {
    if (nodes.length === 0) return toast('노드가 없습니다.', 'error');
    setStatus('미리보기 생성 중...');
    try {
      const res  = await fetch(`${API}/preview`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ graph: buildGraphJSON() }),
      });
      const data = await res.json();
      if (data.error) throw new Error(data.error);
      setPreview(`http://localhost:4010${data.url}`);
      toast('✅ 미리보기 생성됨', 'success');
      setStatus('미리보기 중');
    } catch (e) {
      toast('미리보기 실패: ' + e.message, 'error');
      setStatus('오류');
    }
  }

  // ── AI 노드 생성 ─────────────────────────────────────────────
  async function handleAiGenerate() {
    if (!aiPrompt.trim()) return toast('설명을 입력하세요', 'error');
    setAiLoading(true);
    setStatus('AI 생성 중...');
    try {
      const res  = await fetch(`${API}/ai/generate`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ prompt: aiPrompt }),
      });
      const data = await res.json();
      if (data.error) throw new Error(data.error);

      // 기존 노드 id 충돌 방지: id에 현재 시퀀스 오프셋 추가
      const offset = nodeIdSeq;
      const remap  = {};
      (data.nodes || []).forEach(n => { remap[n.id] = `node-${nodeIdSeq++}`; });

      const newNodes = (data.nodes || []).map(n => ({
        id:       remap[n.id],
        type:     `fw-${n.type}`,
        position: n.position || { x: 100, y: 100 },
        data: {
          nodeType:     `fw-${n.type}`,
          subtype:      n.subtype,
          label:        n.label,
          icon:         n.icon || '⬡',
          props:        { ...(n.props || {}) },
          onPropChange: (k, v) => updateProp(remap[n.id], k, v),
        },
      }));

      const newEdges = (data.edges || []).map((e, i) => ({
        id:           `ai-edge-${offset}-${i}`,
        source:       remap[e.source] || e.source,
        target:       remap[e.target] || e.target,
        sourceHandle: e.sourceHandle || 'out',
        targetHandle: e.targetHandle || 'in',
        animated:     true,
        style:        { stroke: '#ec4899' },
      }));

      setNodes(ns => [...ns, ...newNodes]);
      setEdges(es => [...es, ...newEdges]);
      setShowAi(false);
      setAiPrompt('');
      toast(`✨ ${newNodes.length}개 노드 생성 (${data.source || 'ai'})`, 'success');
      setStatus(`AI 생성 완료 - ${data.description || ''}`);
    } catch (e) {
      toast('AI 생성 실패: ' + e.message, 'error');
      setStatus('오류');
    } finally {
      setAiLoading(false);
    }
  }

  // ── 초기화 ───────────────────────────────────────────────────
  function handleClear() {
    setNodes([]); setEdges([]); setSelected(null); setPreview(null);
    nodeIdSeq = 1;
    toast('캔버스 초기화됨');
    setStatus('준비');
  }

  // ── 선택 노드 props 패널 ──────────────────────────────────────
  const selNode = selected ? nodes.find(n => n.id === selected.id) : null;

  function PropsPanel() {
    if (!selNode) return h('div', { className: 'props-panel' },
      h('div', { className: 'props-panel-title' }, '속성'),
      h('div', { className: 'props-empty' }, '노드를 선택하세요'),
    );

    const { props, label, subtype } = selNode.data;
    return h('div', { className: 'props-panel' },
      h('div', { className: 'props-panel-title' }, `속성 — ${label}`),
      h('div', { className: 'props-form' },
        h('div', { className: 'props-section-title' }, subtype?.toUpperCase()),
        h('div', { className: 'props-sep' }),
        ...Object.entries(props).map(([k, v]) =>
          h('div', { className: 'props-field', key: k },
            h('label', null, k),
            h('input', {
              value: String(v),
              onChange: e => updateProp(selNode.id, k, e.target.value),
            }),
          )
        ),
      ),
    );
  }

  // ─── 렌더 ─────────────────────────────────────────────────────
  return h('div', { id: 'root' },

    // Toolbar
    h('div', { className: 'toolbar' },
      h('span', { className: 'toolbar-logo' }, '⚡ FreeWire'),
      h('div',  { className: 'toolbar-sep' }),
      h('button', { className: 'btn btn-ai',       onClick: () => setShowAi(v => !v) }, '✨ AI 생성'),
      h('div',  { className: 'toolbar-sep' }),
      h('button', { className: 'btn btn-ghost',    onClick: handleCompile }, '컴파일'),
      h('button', { className: 'btn btn-primary',  onClick: handlePreview }, '▶ 미리보기'),
      h('button', { className: 'btn btn-danger',   onClick: handleClear   }, '초기화'),
      h('div',  { className: 'toolbar-sep' }),
      h('span', { style: { fontSize: 12, color: 'var(--text-muted)' } }, `노드 ${nodes.length}개 | 엣지 ${edges.length}개`),
      h('div',  { className: 'toolbar-status' },
        h('div', { className: 'status-dot' }),
        status,
      ),
    ),

    // Workspace
    h('div', { className: 'workspace' },

      // Palette
      h('div', { className: 'palette' },
        h('div', { className: 'palette-title' }, '노드 팔레트'),
        ...PALETTE.map(group =>
          h('div', { className: 'palette-group', key: group.category },
            h('div', { className: 'palette-group-label' }, group.category),
            ...group.items.map(item =>
              h('div', {
                className: 'palette-item',
                key: item.subtype,
                draggable: true,
                onDragStart: e => onDragStart(e, item),
              },
                h('div', { className: 'palette-dot', style: { background: group.color } }),
                h('span', null, item.icon + ' ' + item.label),
              )
            )
          )
        ),
      ),

      // Canvas
      h('div', { className: 'canvas-wrap', ref: canvasRef,
                 onDrop, onDragOver },
        h(ReactFlow, {
          nodes, edges,
          onNodesChange, onEdgesChange, onConnect,
          onNodeClick, onPaneClick,
          nodeTypes: NODE_TYPES,
          fitView: true,
          deleteKeyCode: 'Backspace',
        },
          h(Background, { color: '#2e2e3e', gap: 20 }),
          h(Controls),
          h(MiniMap, { nodeColor: n => TYPE_COLORS[n.type] || '#6366f1',
                       maskColor: 'rgba(0,0,0,.6)' }),
        ),
      ),

      // Props Panel
      h(PropsPanel),
    ),

    // AI 입력 패널
    showAi && h('div', { className: 'ai-panel' },
      h('div', { className: 'ai-panel-header' },
        h('span', null, '✨ AI 노드 생성'),
        h('span', { className: 'preview-close', onClick: () => setShowAi(false) }, '✕'),
      ),
      h('div', { className: 'ai-panel-body' },
        h('p', { className: 'ai-hint' }, '만들고 싶은 UI를 설명해주세요'),
        h('div', { className: 'ai-examples' },
          ['카운터 앱', '로그인 폼', '투두 리스트', '계산기', '프로필 카드'].map(ex =>
            h('span', {
              key: ex, className: 'ai-example-chip',
              onClick: () => setAiPrompt(ex),
            }, ex)
          )
        ),
        h('textarea', {
          className:   'ai-input',
          placeholder: '예: 카운터 만들어줘, 로그인 폼 만들어줘...',
          value:       aiPrompt,
          rows:        3,
          onChange:    e => setAiPrompt(e.target.value),
          onKeyDown:   e => { if (e.key === 'Enter' && e.ctrlKey) handleAiGenerate(); },
        }),
        h('button', {
          className: `btn btn-ai${aiLoading ? ' disabled' : ''}`,
          onClick:   handleAiGenerate,
          disabled:  aiLoading,
        }, aiLoading ? '생성 중...' : '✨ 생성 (Ctrl+Enter)'),
      ),
    ),

    // Preview Panel
    preview && h('div', { className: 'preview-panel' },
      h('div', { className: 'preview-header' },
        h('span', null, '⚡ 미리보기'),
        h('span', { className: 'preview-close',
                    onClick: () => setPreview(null) }, '✕'),
      ),
      h('iframe', { className: 'preview-frame', src: preview }),
    ),

    // Toasts
    h('div', { className: 'toast-wrap' },
      ...toasts.map(t => h('div', { className: `toast ${t.type}`, key: t.id }, t.msg)),
    ),
  );
}

createRoot(document.getElementById('root')).render(h(App));

