  }

  /** 마지막 실행 결과 */
  lastResult() { return this.history[this.history.length - 1]?.result || null; }

  /** 히스토리 초기화 */
  clearHistory() { this.history = []; }
}

// ─── WASM Bridge 인터페이스 (미래 확장용) ───────────────────────
const WASMBridge = {
  _executor: new BrowserExecutor(),
  _ready: true,

  /** WASM 준비 여부 */
  isReady() { return this._ready; },

  /** .free 코드 컴파일 */
