/**
 * FreeWire Phase 6 - BrowserExecutor + WASM Bridge 테스트
 */

const { BrowserExecutor, WASMBridge, FreeLangParser,
        CSSCompiler, JSCompiler, HTMLCompiler } = require('../wasm/browser-executor');

let pass = 0, fail = 0;

function test(name, fn) {
  try { fn(); console.log(`  ✅ ${name}`); pass++; }
  catch (e) { console.log(`  ❌ ${name}: ${e.message}`); fail++; }
}
function assert(cond, msg)        { if (!cond) throw new Error(msg || '실패'); }
function assertInc(str, sub)      { if (!str.includes(sub)) throw new Error(`"${sub}" 없음`); }
function assertNotInc(str, sub)   { if (str.includes(sub))  throw new Error(`"${sub}" 있으면 안 됨`); }

// ─── 1. FreeLangParser ───────────────────────────────────────────
console.log('\n[1] FreeLangParser');

const COUNTER_CODE = `component Counter {
  props { title: string = "카운터"; }
  style { .wrap { display: flex; } }
  script { let count = 0; function set_count(v) { count = v; } }
  markup { <div class="wrap"><span>{{count}}</span></div> }
}`;

test('컴포넌트 이름 추출', () => {
  const p = new FreeLangParser().parse(COUNTER_CODE);
  assert(p.name === 'Counter', `name: ${p.name}`);
});
test('style 블록 추출', () => {
  const p = new FreeLangParser().parse(COUNTER_CODE);
  assertInc(p.style, '.wrap');
  assertInc(p.style, 'display: flex');
});
test('script 블록 추출', () => {
  const p = new FreeLangParser().parse(COUNTER_CODE);
  assertInc(p.script, 'let count = 0');
  assertInc(p.script, 'set_count');
});
test('markup 블록 추출', () => {
  const p = new FreeLangParser().parse(COUNTER_CODE);
  assertInc(p.markup, '<div class="wrap">');
  assertInc(p.markup, '{{count}}');
});
test('props 블록 파싱', () => {
  const p = new FreeLangParser().parse(COUNTER_CODE);
  assert(p.props.title === '카운터', `props.title: ${JSON.stringify(p.props)}`);
});
test('중첩 {} 처리', () => {
  const code = `component A {
    script { function f() { return { x: 1 }; } }
    markup { <div></div> }
  }`;
  const p = new FreeLangParser().parse(code);
  assertInc(p.script, 'function f');
});

// ─── 2. CSSCompiler ─────────────────────────────────────────────
console.log('\n[2] CSSCompiler');
const css = new CSSCompiler();

test('camelCase → kebab-case', () => {
  const out = css.compile('fontSize: 16px; backgroundColor: red;');
  assertInc(out, 'font-size');
  assertInc(out, 'background-color');
});
test('셀렉터 유지', () => {
  const out = css.compile('.btn { color: blue; }');
  assertInc(out, '.btn');
});
test('@keyframes 유지', () => {
  const out = css.compile('@keyframes pulse { 0% { opacity:0 } 100% { opacity:1 } }');
  assertInc(out, '@keyframes');
  assertInc(out, 'pulse');
});
test('빈 입력 → 빈 문자열', () => {
  assert(css.compile('') === '');
  assert(css.compile('   \n  ') === '');
});

// ─── 3. JSCompiler ──────────────────────────────────────────────
console.log('\n[3] JSCompiler');
const jsComp = new JSCompiler();

test('IIFE 래퍼', () => {
  const out = jsComp.compile('let x = 1;', 'Test');
  assertInc(out, '(function(fw)');
  assertInc(out, 'let x = 1');
  assertInc(out, '})({})');
});
test('컴포넌트 이름 주석', () => {
  const out = jsComp.compile('', 'MyComp');
  assertInc(out, '/* FreeWire: MyComp */');
});
test('state setter → __fw_update 트리거', () => {
  const out = jsComp.compile('let n = 0; function set_n(v) { n = v; }', 'T');
  assertInc(out, '__fw_update');
  assertInc(out, 'set_n');
});
test('DOMContentLoaded 포함', () => {
  const out = jsComp.compile('let x = 1;', 'T');
  assertInc(out, 'DOMContentLoaded');
});
test('data-fw-action 바인딩', () => {
  const out = jsComp.compile('function click() {}', 'T');
  assertInc(out, 'data-fw-action');
});

// ─── 4. HTMLCompiler ────────────────────────────────────────────
console.log('\n[4] HTMLCompiler');
const htmlComp = new HTMLCompiler();

test('markup 블록 태그 제거', () => {
  const out = htmlComp.compile('markup { <div>안녕</div> }');
  assertInc(out, '<div>안녕</div>');
  assertNotInc(out, 'markup {');
});
test('{{변수}} → data-fw-bind', () => {
  const out = htmlComp.compile('<p>{{count}}</p>');
  assertInc(out, 'data-fw-bind="count"');
  assertInc(out, '<span');
});
test('다중 변수 바인딩', () => {
  const out = htmlComp.compile('<span>{{a}}</span><span>{{b}}</span>');
  assertInc(out, 'data-fw-bind="a"');
  assertInc(out, 'data-fw-bind="b"');
});
test('빈 입력 → 빈 문자열', () => {
  assert(htmlComp.compile('') === '');
});

// ─── 5. BrowserExecutor.execute() ───────────────────────────────
console.log('\n[5] BrowserExecutor.execute()');
const exec = new BrowserExecutor();

test('기본 컴포넌트 실행', () => {
  const r = exec.execute(COUNTER_CODE);
  assert(typeof r.html === 'string', 'html');
  assert(typeof r.css  === 'string', 'css');
  assert(typeof r.js   === 'string', 'js');
  assert(r.name === 'Counter', `name: ${r.name}`);
});
test('stats 포함', () => {
  const r = exec.execute(COUNTER_CODE);
  assert(typeof r.stats.parseMs   === 'number', 'parseMs');
  assert(typeof r.stats.htmlBytes === 'number', 'htmlBytes');
  assert(r.stats.htmlBytes > 0, 'htmlBytes > 0');
});
test('style 있으면 hasStyle=true', () => {
  const r = exec.execute(COUNTER_CODE);
  assert(r.stats.hasStyle === true);
});
test('script 있으면 hasScript=true', () => {
  const r = exec.execute(COUNTER_CODE);
  assert(r.stats.hasScript === true);
});
test('history에 기록됨', () => {
  const e = new BrowserExecutor();
  e.execute(COUNTER_CODE);
  assert(e.history.length === 1);
  assert(e.history[0].code === COUNTER_CODE);
});
test('history 50개 초과 시 자동 정리', () => {
  const e = new BrowserExecutor();
  for (let i = 0; i < 55; i++) e.execute(COUNTER_CODE);
  assert(e.history.length === 50, `history: ${e.history.length}`);
});

// ─── 6. buildPreviewHTML ────────────────────────────────────────
console.log('\n[6] buildPreviewHTML');

test('완전한 HTML 문서 생성', () => {
  const r    = exec.execute(COUNTER_CODE);
  const html = exec.buildPreviewHTML(r);
  assertInc(html, '<!DOCTYPE html>');
  assertInc(html, '<meta charset="UTF-8">');
  assertInc(html, 'id="fw-root"');
  assertInc(html, 'FreeWire');
});
test('CSS 인라인 포함', () => {
  const r    = exec.execute(COUNTER_CODE);
  const html = exec.buildPreviewHTML(r);
  assertInc(html, '.wrap');
});
test('JS 인라인 포함', () => {
  const r    = exec.execute(COUNTER_CODE);
  const html = exec.buildPreviewHTML(r);
  assertInc(html, 'set_count');
});
test('내용 없으면 기본 메시지', () => {
  const html = exec.buildPreviewHTML({ html: '', css: '', js: '' });
  assertInc(html, '내용 없음');
});

// ─── 7. WASMBridge ──────────────────────────────────────────────
console.log('\n[7] WASMBridge');

test('isReady() = true', () => {
  assert(WASMBridge.isReady() === true);
});
test('compile() 결과 구조', () => {
  const r = WASMBridge.compile(COUNTER_CODE);
  assert(r.html !== undefined && r.css !== undefined && r.js !== undefined);
  assert(r.name === 'Counter');
});
test('preview() → 완전한 HTML', () => {
  const html = WASMBridge.preview(COUNTER_CODE);
  assertInc(html, '<!DOCTYPE html>');
  assertInc(html, 'Counter');
});
test('history() 배열 반환', () => {
  assert(Array.isArray(WASMBridge.history()));
});

// ─── 8. 실제 예제 코드들 실행 테스트 ────────────────────────────
console.log('\n[8] 예제 코드 실행 검증');

const CARD_CODE = `component ProfileCard {
  style { .card { border-radius: 12px; padding: 20px; } }
  markup { <div class="card"><h2>김개발</h2><p>FreeLang 개발자</p></div> }
}`;

const ANIM_CODE = `component AnimBox {
  style {
    .box { animation: spin 1s linear infinite; }
    @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
  }
  markup { <div class="box">⚡</div> }
}`;

test('카드 컴포넌트 실행', () => {
  const r = exec.execute(CARD_CODE);
  assertInc(r.html, '김개발');
  assertInc(r.css,  'border-radius');
});
test('@keyframes 포함 CSS 컴파일', () => {
  const r = exec.execute(ANIM_CODE);
  assertInc(r.css, '@keyframes');
  assertInc(r.css, 'spin');
});
test('스크립트 없는 컴포넌트 hasScript=false', () => {
  const r = exec.execute(CARD_CODE);
  assert(r.stats.hasScript === false, `hasScript: ${r.stats.hasScript}`);
});
test('데이터 바인딩 {{}} → data-fw-bind 변환', () => {
  const r = exec.execute(COUNTER_CODE);
  assertInc(r.html, 'data-fw-bind="count"');
});

